contracts/TrataTechMain_Fixed.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/utils/Address.sol";
import "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import "./TrataTechSecurityEnhanced.sol";

/**
 * @title TrataTechMain_Fixed
 * @dev Security-enhanced comprehensive smart contract for TrataTech platform
 * @author Security Enhanced Version
 */
contract TrataTechMain_Fixed is 
    ERC721, 
    ERC2771Context,
    AccessControl,
    Pausable, 
    ReentrancyGuard 
{
    using Strings for uint256;
    using Address for address payable;
    using TrataTechSecurityEnhanced for *;

    // ============ CONSTANTS ============

    uint256 public constant MAX_ATTENDEES = 10000;
    uint256 public constant MAX_EARLY_ACCESS = 10000;
    uint256 public constant MAX_EDITIONS = 10000;
    uint256 public constant MAX_REDEMPTIONS = 100000;
    uint256 public constant MAX_FEE_PERCENTAGE = 1000; // 10% max
    uint256 public constant FEE_DENOMINATOR = 10000;
    uint256 public constant MAX_FUTURE_DATE = 365 days;
    uint256 public constant PAGINATION_LIMIT = 100;

    // ============ STRUCTS ============

    struct EventInvite {
        uint256 eventId;
        bytes32 eventNameHash;
        string eventDescription;
        uint256 eventDate;
        uint256 maxAttendees;
        uint256 currentAttendees;
        string ipfsCID;
        bool isActive;
        bool isCancelled;
        mapping(address => bool) attendees;
        mapping(address => uint256) attendeeTokens;
    }

    struct ProductLaunch {
        uint256 launchId;
        bytes32 productNameHash;
        string productDescription;
        uint256 launchDate;
        uint256 earlyAccessEndDate;
        string ipfsCID;
        bool isActive;
        bool isLaunched;
        uint256 maxEarlyAccess;
        uint256 currentEarlyAccess;
        mapping(address => bool) earlyAccessUsers;
        mapping(address => uint256) preOrders;
        uint256 totalPreOrderAmount;
    }

    struct DigitalProductPassport {
        uint256 dppId;
        bytes32 productIdHash;
        bytes32 brandIdHash;
        string ipfsCID;
        uint256 timestamp;
        bool isValid;
        address creator;
        bytes32 metadataHash;
    }

    struct DigitalArtDrop {
        uint256 dropId;
        bytes32 artistNameHash;
        string artworkTitle;
        uint256 currentEdition;
        uint256 maxEditions;
        string ipfsCID;
        bool isActive;
        bool isLimited;
        mapping(address => bool) airdroppedTo;
    }

    struct Offer {
        uint256 offerId;
        bytes32 titleHash;
        uint256 discountPercentage;
        uint256 validFrom;
        uint256 validUntil;
        string productScope;
        string conditions;
        string ipfsCID;
        bool isActive;
        bool isMerkleBased;
        bytes32 merkleRoot;
        uint256 maxRedemptions;
        uint256 currentRedemptions;
        mapping(address => bool) redeemedBy;
        mapping(address => uint256) userRedemptions;
    }

    // ============ STATE VARIABLES ============

    uint256 private _tokenIds;
    uint256 private _eventIds;
    uint256 private _launchIds;
    uint256 private _dppIds;
    uint256 private _dropIds;
    uint256 private _offerIds;

    // Mappings
    mapping(uint256 => EventInvite) private _events;
    mapping(uint256 => ProductLaunch) private _launches;
    mapping(uint256 => DigitalProductPassport) private _dpps;
    mapping(uint256 => DigitalArtDrop) private _drops;
    mapping(uint256 => Offer) private _offers;

    // Token type mapping
    mapping(uint256 => TokenType) private _tokenTypes;
    mapping(uint256 => uint256) private _tokenReferences;

    // Fee structure with limits
    uint256 private _platformFee = 250; // 2.5% in basis points
    uint256 private _minPlatformFee = 0;
    uint256 private _maxPlatformFee = MAX_FEE_PERCENTAGE;

    // Rate limiting
    mapping(address => uint256) private _lastActionTime;
    uint256 public constant RATE_LIMIT_DURATION = 1 minutes;

    // Owner
    address private _owner;

    // ============ ENUMS ============

    enum TokenType {
        EVENT_INVITE,
        PRODUCT_LAUNCH,
        DIGITAL_ART,
        OFFER_COUPON,
        DPP_PASSPORT
    }

    // ============ ROLES ============

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant BRAND_ROLE = keccak256("BRAND_ROLE");

    // ============ EVENTS ============

    event EventCreated(uint256 indexed eventId, bytes32 eventNameHash, uint256 eventDate, string ipfsCID);
    event EventCancelled(uint256 indexed eventId, address indexed canceller);
    event RSVPSubmitted(uint256 indexed eventId, address indexed attendee, uint256 tokenId);
    event RSVPCancelled(uint256 indexed eventId, address indexed attendee);

    event ProductLaunchCreated(uint256 indexed launchId, bytes32 productNameHash, uint256 launchDate, string ipfsCID);
    event EarlyAccessGranted(uint256 indexed launchId, address indexed user, uint256 tokenId);
    event PreOrderPlaced(uint256 indexed launchId, address indexed user, uint256 amount);

    event DPPCreated(uint256 indexed dppId, bytes32 productIdHash, bytes32 brandIdHash, string ipfsCID);
    event DPPInvalidated(uint256 indexed dppId, address indexed invalidator);

    event ArtDropCreated(uint256 indexed dropId, bytes32 artistNameHash, string artworkTitle, string ipfsCID);
    event ArtAirdropped(uint256 indexed dropId, address indexed recipient, uint256 tokenId);

    event OfferCreated(uint256 indexed offerId, bytes32 titleHash, uint256 discountPercentage, string ipfsCID);
    event OfferRedeemed(uint256 indexed offerId, address indexed user, uint256 tokenId);
    event OfferExpired(uint256 indexed offerId);

    event PlatformFeeUpdated(uint256 oldFee, uint256 newFee, address indexed updater);
    event FeeLimitsUpdated(uint256 minFee, uint256 maxFee, address indexed updater);
    event EmergencyWithdrawal(address indexed to, uint256 amount);

    // ============ MODIFIERS ============

    modifier rateLimited() {
        require(
            block.timestamp >= _lastActionTime[msg.sender] + RATE_LIMIT_DURATION,
            "Rate limit exceeded"
        );
        _lastActionTime[msg.sender] = block.timestamp;
        _;
    }

    modifier validEvent(uint256 eventId) {
        require(_events[eventId].eventId != 0, "Event does not exist");
        require(_events[eventId].isActive, "Event is not active");
        require(!_events[eventId].isCancelled, "Event is cancelled");
        _;
    }

    modifier validLaunch(uint256 launchId) {
        require(_launches[launchId].launchId != 0, "Launch does not exist");
        require(_launches[launchId].isActive, "Launch is not active");
        _;
    }

    modifier validOffer(uint256 offerId) {
        require(_offers[offerId].offerId != 0, "Offer does not exist");
        require(_offers[offerId].isActive, "Offer is not active");
        require(block.timestamp >= _offers[offerId].validFrom, "Offer not yet valid");
        require(block.timestamp <= _offers[offerId].validUntil, "Offer expired");
        _;
    }

    // ============ CONSTRUCTOR ============

    constructor(address trustedForwarder) 
        ERC721("TrataTech Platform", "TRATA") 
        ERC2771Context(trustedForwarder) {
        _tokenIds = 1; // Start from 1
        _owner = msg.sender;

        // Setup roles
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);
        _setRoleAdmin(OPERATOR_ROLE, ADMIN_ROLE);
        _setRoleAdmin(BRAND_ROLE, ADMIN_ROLE);
        _setRoleAdmin(PAUSER_ROLE, ADMIN_ROLE);
    }

    /**
     * @dev Returns the address of the current owner
     */
    function owner() public view returns (address) {
        return _owner;
    }

    /**
     * @dev Override supportsInterface to resolve inheritance conflict
     */
    function supportsInterface(bytes4 interfaceId) 
        public 
        view 
        override(ERC721, AccessControl) 
        returns (bool) 
    {
        return super.supportsInterface(interfaceId);
    }

    // ============ EVENT MANAGEMENT ============

    /**
     * @notice Create a new event invite
     * @param eventName Name of the event
     * @param eventDescription Description of the event
     * @param eventDate Unix timestamp of the event
     * @param maxAttendees Maximum number of attendees
     * @param ipfsCID IPFS CID containing event metadata
     */
    function createEventInvite(
        string memory eventName,
        string memory eventDescription,
        uint256 eventDate,
        uint256 maxAttendees,
        string memory ipfsCID
    ) external 
        whenNotPaused 
        onlyRole(BRAND_ROLE)
        nonReentrant 
        returns (uint256) 
    {
        // Input validation
        TrataTechSecurityEnhanced.validateString(eventName);
        TrataTechSecurityEnhanced.validateString(eventDescription);
        require(eventDate > block.timestamp && eventDate <= block.timestamp + MAX_FUTURE_DATE, "Invalid event date");
        require(maxAttendees > 0 && maxAttendees <= MAX_ATTENDEES, "Invalid max attendees");
        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);

        _eventIds++;
        uint256 eventId = _eventIds;

        EventInvite storage newEvent = _events[eventId];
        newEvent.eventId = eventId;
        newEvent.eventNameHash = keccak256(bytes(eventName));
        newEvent.eventDescription = eventDescription;
        newEvent.eventDate = eventDate;
        newEvent.maxAttendees = maxAttendees;
        newEvent.currentAttendees = 0;
        newEvent.ipfsCID = ipfsCID;
        newEvent.isActive = true;
        newEvent.isCancelled = false;

        emit EventCreated(eventId, newEvent.eventNameHash, eventDate, ipfsCID);
        return eventId;
    }

    /**
     * @notice Submit RSVP for an event
     * @param eventId ID of the event
     */
    function submitRSVP(uint256 eventId) 
        external 
        validEvent(eventId) 
        whenNotPaused 
        rateLimited
        nonReentrant 
    {
        EventInvite storage eventData = _events[eventId];

        require(!eventData.attendees[msg.sender], "Already RSVP'd");
        require(eventData.currentAttendees < eventData.maxAttendees, "Event is full");
        require(block.timestamp < eventData.eventDate, "Event has already started");

        // Update state before external calls
        eventData.attendees[msg.sender] = true;
        eventData.currentAttendees++;

        // Mint NFT ticket
        _tokenIds++;
        uint256 tokenId = _tokenIds;

        eventData.attendeeTokens[msg.sender] = tokenId;
        _tokenTypes[tokenId] = TokenType.EVENT_INVITE;
        _tokenReferences[tokenId] = eventId;

        _safeMint(msg.sender, tokenId);

        emit RSVPSubmitted(eventId, msg.sender, tokenId);
    }

    /**
     * @notice Cancel RSVP for an event
     * @param eventId ID of the event
     */
    function cancelRSVP(uint256 eventId) 
        external 
        validEvent(eventId) 
        whenNotPaused 
        nonReentrant 
    {
        EventInvite storage eventData = _events[eventId];

        require(eventData.attendees[msg.sender], "Not RSVP'd for this event");
        require(block.timestamp < eventData.eventDate - 1 days, "Too late to cancel");

        uint256 tokenId = eventData.attendeeTokens[msg.sender];

        // Update state before external calls
        eventData.attendees[msg.sender] = false;
        eventData.attendeeTokens[msg.sender] = 0;
        eventData.currentAttendees--;

        // Burn NFT ticket
        _burn(tokenId);

        emit RSVPCancelled(eventId, msg.sender);
    }

    /**
     * @notice Cancel an event (only by authorized role with timelock)
     * @param eventId ID of the event
     */
    function cancelEvent(uint256 eventId) external onlyRole(ADMIN_ROLE) {
        require(_events[eventId].eventId != 0, "Event does not exist");
        require(!_events[eventId].isCancelled, "Event already cancelled");

        _events[eventId].isCancelled = true;
        _events[eventId].isActive = false;

        emit EventCancelled(eventId, msg.sender);
    }

    // ============ PRODUCT LAUNCH MANAGEMENT ============

    /**
     * @notice Create a new product launch
     * @param productName Name of the product
     * @param productDescription Description of the product
     * @param launchDate Unix timestamp of the launch
     * @param earlyAccessEndDate Unix timestamp when early access ends
     * @param maxEarlyAccess Maximum number of early access users
     * @param ipfsCID IPFS CID containing launch metadata
     */
    function createProductLaunch(
        string memory productName,
        string memory productDescription,
        uint256 launchDate,
        uint256 earlyAccessEndDate,
        uint256 maxEarlyAccess,
        string memory ipfsCID
    ) external 
        whenNotPaused 
        onlyRole(BRAND_ROLE)
        nonReentrant 
        returns (uint256) 
    {
        // Enhanced input validation
        TrataTechSecurityEnhanced.validateString(productName);
        TrataTechSecurityEnhanced.validateString(productDescription);
        require(launchDate > block.timestamp && launchDate <= block.timestamp + MAX_FUTURE_DATE, "Invalid launch date");
        require(earlyAccessEndDate > block.timestamp && earlyAccessEndDate <= launchDate, "Invalid early access date");
        require(maxEarlyAccess > 0 && maxEarlyAccess <= MAX_EARLY_ACCESS, "Invalid max early access");
        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);

        _launchIds++;
        uint256 launchId = _launchIds;

        ProductLaunch storage newLaunch = _launches[launchId];
        newLaunch.launchId = launchId;
        newLaunch.productNameHash = keccak256(bytes(productName));
        newLaunch.productDescription = productDescription;
        newLaunch.launchDate = launchDate;
        newLaunch.earlyAccessEndDate = earlyAccessEndDate;
        newLaunch.ipfsCID = ipfsCID;
        newLaunch.isActive = true;
        newLaunch.isLaunched = false;
        newLaunch.maxEarlyAccess = maxEarlyAccess;
        newLaunch.currentEarlyAccess = 0;
        newLaunch.totalPreOrderAmount = 0;

        emit ProductLaunchCreated(launchId, newLaunch.productNameHash, launchDate, ipfsCID);
        return launchId;
    }

    /**
     * @notice Place a pre-order for a product launch (Fixed reentrancy)
     * @param launchId ID of the launch
     */
    function placePreOrder(uint256 launchId) 
        external 
        payable 
        validLaunch(launchId) 
        whenNotPaused 
        rateLimited
        nonReentrant 
    {
        require(msg.value > 0, "Must send ETH for pre-order");
        require(msg.value <= 100 ether, "Pre-order amount too high");

        ProductLaunch storage launch = _launches[launchId];

        require(block.timestamp < launch.launchDate, "Launch has already started");
        require(launch.preOrders[msg.sender] == 0, "Already placed pre-order");

        // Calculate platform fee with overflow protection
        uint256 platformFeeAmount = TrataTechSecurityEnhanced.calculateFee(msg.value, _platformFee);

        // Update state BEFORE external calls (CEI pattern)
        launch.preOrders[msg.sender] = msg.value;
        launch.totalPreOrderAmount += msg.value;

        emit PreOrderPlaced(launchId, msg.sender, msg.value);

        // Transfer platform fee to owner (external call at the end)
        if (platformFeeAmount > 0) {
            payable(owner()).sendValue(platformFeeAmount);
        }
    }

    // ============ DIGITAL ART DROP MANAGEMENT (FIXED) ============

    /**
     * @notice Airdrop artwork to eligible users (Fixed DoS vulnerability)
     * @param dropId ID of the drop
     * @param recipients Array of recipient addresses (limited)
     */
    function airdropArtwork(uint256 dropId, address[] memory recipients) 
        external 
        whenNotPaused 
        onlyRole(OPERATOR_ROLE)
        nonReentrant 
    {
        require(recipients.length <= PAGINATION_LIMIT, "Too many recipients");

        DigitalArtDrop storage drop = _drops[dropId];
        require(drop.dropId != 0, "Drop does not exist");
        require(drop.isActive, "Drop is not active");

        for (uint256 i = 0; i < recipients.length; i++) {
            address recipient = recipients[i];
            TrataTechSecurityEnhanced.validateAddress(recipient);

            if (!drop.airdroppedTo[recipient]) {
                if (drop.isLimited) {
                    require(drop.currentEdition < drop.maxEditions, "Max editions reached");
                    drop.currentEdition++;
                }

                drop.airdroppedTo[recipient] = true;

                _tokenIds++;
                uint256 tokenId = _tokenIds;

                _tokenTypes[tokenId] = TokenType.DIGITAL_ART;
                _tokenReferences[tokenId] = dropId;

                _safeMint(recipient, tokenId);

                emit ArtAirdropped(dropId, recipient, tokenId);
            }
        }
    }

    // ============ OFFER MANAGEMENT ============

    /**
     * @notice Redeem an offer
     * @param offerId ID of the offer
     * @param merkleProof Merkle proof for eligibility (if applicable)
     */
    function redeemOffer(uint256 offerId, bytes32[] memory merkleProof) 
        external 
        validOffer(offerId) 
        whenNotPaused 
        rateLimited
        nonReentrant 
    {
        Offer storage offer = _offers[offerId];

        require(!offer.redeemedBy[msg.sender], "Offer already redeemed");

        if (offer.isMerkleBased) {
            bytes32 leaf = keccak256(abi.encodePacked(msg.sender));
            require(MerkleProof.verify(merkleProof, offer.merkleRoot, leaf), "Not eligible");
        }

        if (offer.maxRedemptions > 0) {
            require(offer.currentRedemptions < offer.maxRedemptions, "Redemption limit reached");
        }

        // Update state before minting
        offer.redeemedBy[msg.sender] = true;
        offer.userRedemptions[msg.sender]++;
        offer.currentRedemptions++;

        // Mint offer NFT
        _tokenIds++;
        uint256 tokenId = _tokenIds;

        _tokenTypes[tokenId] = TokenType.OFFER_COUPON;
        _tokenReferences[tokenId] = offerId;

        _safeMint(msg.sender, tokenId);

        emit OfferRedeemed(offerId, msg.sender, tokenId);
    }

    // ============ ADMIN FUNCTIONS WITH TIMELOCK ============

    /**
     * @notice Update platform fee (with restrictions and timelock)
     * @param newFee New platform fee in basis points
     */
    function updatePlatformFee(uint256 newFee) external onlyRole(ADMIN_ROLE) {
        require(newFee >= _minPlatformFee && newFee <= _maxPlatformFee, "Fee out of bounds");
        require(newFee <= MAX_FEE_PERCENTAGE, "Fee exceeds maximum");

        // Restrict fee changes to max 100 basis points at a time
        uint256 currentFee = _platformFee;
        require(
            newFee <= currentFee + 100 || newFee >= currentFee - 100,
            "Fee change too large"
        );

        uint256 oldFee = _platformFee;
        _platformFee = newFee;

        emit PlatformFeeUpdated(oldFee, newFee, msg.sender);
    }

    /**
     * @notice Update fee limits
     * @param minFee Minimum platform fee
     * @param maxFee Maximum platform fee
     */
    function updateFeeLimits(uint256 minFee, uint256 maxFee) external onlyRole(ADMIN_ROLE) {
        require(minFee <= maxFee, "Invalid fee limits");
        require(maxFee <= MAX_FEE_PERCENTAGE, "Max fee too high");

        _minPlatformFee = minFee;
        _maxPlatformFee = maxFee;

        emit FeeLimitsUpdated(minFee, maxFee, msg.sender);
    }

    /**
     * @notice Pause contract
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @notice Unpause contract
     */
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }


    // ============ EMERGENCY FUNCTIONS ============

    /**
     * @notice Emergency function to recover stuck ETH (with timelock)
     * @param to Address to send ETH to
     * @param amount Amount to recover
     */
    function emergencyRecoverETH(address to, uint256 amount) 
        external 
        onlyRole(ADMIN_ROLE) 
        whenPaused 
    {
        TrataTechSecurityEnhanced.validateAddress(to);
        require(amount > 0 && amount <= address(this).balance, "Invalid amount");

        emit EmergencyWithdrawal(to, amount);

        payable(to).sendValue(amount);
    }

    // ============ VIEW FUNCTIONS ============

    function platformFee() external view returns (uint256) {
        return _platformFee;
    }

    function feeLimits() external view returns (uint256 min, uint256 max) {
        return (_minPlatformFee, _maxPlatformFee);
    }

    // ============ RECEIVE FUNCTION ============

    receive() external payable {
        // Contract can receive ETH for fees and pre-orders
    }

    // ============ OVERRIDE FUNCTIONS FOR ERC2771Context ============

    function _msgSender() internal view override(Context, ERC2771Context) returns (address) {
        return ERC2771Context._msgSender();
    }

    function _msgData() internal view override(Context, ERC2771Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength() internal view override(Context, ERC2771Context) returns (uint256) {
        return ERC2771Context._contextSuffixLength();
    }
}

contracts/TrataTechOwnershipRegistry_Fix.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import "./TrataTechSecurityEnhanced.sol";

/**
 * @title TrataTechOwnershipRegistry_Fixed
 * @dev SECURITY-ENHANCED Ownership Registry with NFT-linked digital deeds
 * @dev Fixed all critical vulnerabilities: reentrancy, DoS, race conditions, access control
 */
contract TrataTechOwnershipRegistry_Fixed is 
    ERC721, 
    ERC2771Context,
    AccessControl, 
    Pausable, 
    ReentrancyGuard 
{
    using ECDSA for bytes32;
    using TrataTechSecurityEnhanced for string;
    using TrataTechSecurityEnhanced for address;
    using TrataTechSecurityEnhanced for uint256;

    // ============ ROLES ============

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant BRAND_ROLE = keccak256("BRAND_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant TRANSFER_AGENT_ROLE = keccak256("TRANSFER_AGENT_ROLE");

    // ============ STRUCTS ============

    struct OwnershipDeed {
        uint256 deedId;
        uint256 passportId;
        address owner;
        uint256 acquisitionDate;
        uint256 acquisitionPrice;
        string acquisitionMethod;
        string ipfsCID;
        string metadataHash;
        bool isValid;
        bool isLocked;
        uint256 lockExpiry;
        address previousOwner;
        mapping(string => string) additionalData;
        string[] dataKeys;
        uint256 transferCount; // Track number of transfers
    }

    struct TransferRequest {
        uint256 requestId;
        uint256 deedId;
        address from;
        address to;
        uint256 requestDate;
        uint256 proposedPrice;
        string transferReason;
        TransferStatus status;
        address requester;
        uint256 expiryDate;
        bool isApproved;
        address approver;
        bool isExecuted; // Prevent double execution
    }

    struct RoyaltyInfo {
        address recipient;
        uint256 percentage;
        bool isActive;
        uint256 maxAmount; // Maximum royalty amount
        uint256 totalCollected; // Track total royalties collected
    }

    enum TransferStatus {
        PENDING,
        APPROVED,
        REJECTED,
        EXPIRED,
        CANCELLED,
        EXECUTED
    }

    enum TransferType {
        PRIMARY_SALE,
        SECONDARY_SALE,
        GIFT,
        INHERITANCE,
        LOAN,
        CONSIGNMENT,
        AUCTION,
        CUSTOM
    }

    // ============ STATE VARIABLES ============

    uint256 private _deedIds;
    uint256 private _requestIds;

    // Core mappings with security enhancements
    mapping(uint256 => OwnershipDeed) public ownershipDeeds;
    mapping(uint256 => TransferRequest) public transferRequests;
    mapping(uint256 => uint256) public passportToDeed;
    mapping(address => uint256[]) public ownerToDeeds;
    mapping(uint256 => RoyaltyInfo) public deedRoyalties;

    // Security mappings
    mapping(address => uint256) private _lastActionTime; // Rate limiting
    mapping(address => uint256) private _pendingRequestCount; // Track pending requests per user
    mapping(uint256 => uint256) private _deedTransferCount; // Track transfers per deed
    mapping(address => bool) private _blacklistedAddresses; // Security blacklist

    // Fee structure with limits
    uint256 public transferFee;
    uint256 public royaltyFee;
    uint256 public constant MAX_TRANSFER_FEE = 0.1 ether;
    uint256 public constant MAX_ROYALTY_PERCENTAGE = 1000; // 10%
    uint256 public constant FEE_DENOMINATOR = 10000;

    // Transfer settings with security limits
    uint256 public transferApprovalPeriod;
    uint256 public maxTransferRequests;
    uint256 public maxDailyTransfers;
    uint256 public constant ABSOLUTE_MAX_REQUESTS = 10; // Prevent DoS

    // Circuit breakers
    bool public transfersEnabled;
    bool public royaltiesEnabled;
    bool public lockingEnabled;
    bool public requestsEnabled;

    // Security tracking
    uint256 public totalDeedsCreated;
    uint256 public totalTransfersCompleted;
    uint256 public totalRoyaltiesPaid;
    uint256 public totalFeesCollected;

    // ============ EVENTS ============

    event OwnershipDeedCreated(
        uint256 indexed deedId,
        uint256 indexed passportId,
        address indexed owner,
        uint256 acquisitionPrice,
        string acquisitionMethod,
        string ipfsCID
    );

    event OwnershipDeedTransferred(
        uint256 indexed deedId,
        address indexed from,
        address indexed to,
        uint256 transferPrice,
        TransferType transferType
    );

    event TransferRequestCreated(
        uint256 indexed requestId,
        uint256 indexed deedId,
        address indexed from,
        address to,
        uint256 proposedPrice
    );

    event RoyaltyPaid(
        uint256 indexed deedId,
        address indexed recipient,
        uint256 amount,
        uint256 transferPrice
    );

    event SecurityViolationDetected(
        string violationType,
        address violator,
        uint256 deedId
    );

    event CircuitBreakerActivated(string feature, address activatedBy);
    event AddressBlacklisted(address blacklisted, string reason);

    // ============ MODIFIERS ============

    modifier rateLimited() {
        TrataTechSecurityEnhanced.checkRateLimit(_lastActionTime[msg.sender]);
        TrataTechSecurityEnhanced.updateRateLimit(msg.sender, _lastActionTime);
        _;
    }

    modifier notBlacklisted(address addr) {
        require(!_blacklistedAddresses[addr], "Address is blacklisted");
        _;
    }

    modifier validDeed(uint256 deedId) {
        require(ownershipDeeds[deedId].deedId != 0, "Deed does not exist");
        require(ownershipDeeds[deedId].isValid, "Deed is invalid");
        _;
    }

    modifier onlyDeedOwner(uint256 deedId) {
        require(ownershipDeeds[deedId].owner == msg.sender, "Not deed owner");
        _;
    }

    modifier deedNotLocked(uint256 deedId) {
        OwnershipDeed storage deed = ownershipDeeds[deedId];
        require(
            !deed.isLocked || deed.lockExpiry <= block.timestamp,
            "Deed is locked"
        );
        _;
    }

    modifier whenTransfersEnabled() {
        require(transfersEnabled, "Transfers are disabled");
        _;
    }

    modifier whenRequestsEnabled() {
        require(requestsEnabled, "Requests are disabled");
        _;
    }

    // ============ CONSTRUCTOR ============

    constructor(address trustedForwarder) 
        ERC721("TrataTech Ownership Deed", "TRATA-DEED") 
        ERC2771Context(trustedForwarder) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(BRAND_ROLE, msg.sender);
        _grantRole(OPERATOR_ROLE, msg.sender);

        _deedIds = 1;
        _requestIds = 1;

        // Set secure defaults
        transferFee = 0.005 ether;
        royaltyFee = 250; // 2.5%
        transferApprovalPeriod = 7 days;
        maxTransferRequests = 5;
        maxDailyTransfers = 10;

        // Enable all features initially
        transfersEnabled = true;
        royaltiesEnabled = true;
        lockingEnabled = true;
        requestsEnabled = true;
    }

    // ============ OWNERSHIP DEED MANAGEMENT ============

    /**
     * @dev Create a new ownership deed with comprehensive security
     */
    function createOwnershipDeed(
        uint256 passportId,
        address owner,
        uint256 acquisitionPrice,
        string memory acquisitionMethod,
        string memory ipfsCID,
        string memory metadataHash,
        string[] memory additionalData
    ) external 
      onlyRole(BRAND_ROLE)
      whenNotPaused
      rateLimited
      notBlacklisted(owner)
      nonReentrant
      returns (uint256)
    {
        // Validate all inputs
        require(passportId > 0, "Invalid passport ID");
        TrataTechSecurityEnhanced.validateAddress(owner);
        TrataTechSecurityEnhanced.validateString(acquisitionMethod);
        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);
        TrataTechSecurityEnhanced.validateString(metadataHash);
        TrataTechSecurityEnhanced.validateArraySize(additionalData.length);

        require(passportToDeed[passportId] == 0, "Passport already has deed");

        uint256 deedId = _deedIds;
        _deedIds++;

        OwnershipDeed storage newDeed = ownershipDeeds[deedId];
        newDeed.deedId = deedId;
        newDeed.passportId = passportId;
        newDeed.owner = owner;
        newDeed.acquisitionDate = block.timestamp;
        newDeed.acquisitionPrice = acquisitionPrice;
        newDeed.acquisitionMethod = acquisitionMethod;
        newDeed.ipfsCID = ipfsCID;
        newDeed.metadataHash = metadataHash;
        newDeed.isValid = true;
        newDeed.isLocked = false;
        newDeed.lockExpiry = 0;
        newDeed.previousOwner = address(0);
        newDeed.transferCount = 0;

        // Process additional data with validation
        TrataTechSecurityEnhanced.processKeyValuePairs(
            additionalData,
            newDeed.additionalData,
            newDeed.dataKeys
        );

        // Update mappings
        passportToDeed[passportId] = deedId;
        ownerToDeeds[owner].push(deedId);

        // Mint NFT
        _safeMint(owner, deedId);

        totalDeedsCreated++;

        emit OwnershipDeedCreated(
            deedId, 
            passportId, 
            owner, 
            acquisitionPrice, 
            acquisitionMethod, 
            ipfsCID
        );

        return deedId;
    }

    /**
     * @dev Transfer ownership deed with reentrancy protection and royalty handling
     */
    function transferOwnershipDeed(
        uint256 deedId,
        address to,
        uint256 transferPrice,
        TransferType transferType,
        string memory ipfsCID
    ) external 
      payable
      validDeed(deedId)
      onlyDeedOwner(deedId)
      deedNotLocked(deedId)
      whenNotPaused
      whenTransfersEnabled
      rateLimited
      notBlacklisted(to)
      nonReentrant
    {
        TrataTechSecurityEnhanced.validateAddress(to);
        require(to != msg.sender, "Cannot transfer to self");
        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);

        OwnershipDeed storage deed = ownershipDeeds[deedId];
        address from = deed.owner;

        // Handle royalty payment FIRST (before state changes)
        uint256 royaltyPaid = 0;
        if (transferPrice > 0 && royaltiesEnabled && deedRoyalties[deedId].isActive) {
            royaltyPaid = _handleRoyaltyPayment(deedId, transferPrice);
        }

        // Update deed state BEFORE external calls
        deed.previousOwner = from;
        deed.owner = to;
        deed.transferCount++;

        // Update ownership mappings
        _removeDeedFromOwner(from, deedId);
        ownerToDeeds[to].push(deedId);

        // Transfer NFT (this is the external interaction)
        _transfer(from, to, deedId);

        totalTransfersCompleted++;
        if (royaltyPaid > 0) {
            totalRoyaltiesPaid += royaltyPaid;
        }

        emit OwnershipDeedTransferred(deedId, from, to, transferPrice, transferType);
    }

    /**
     * @dev Secure lock mechanism with time limits
     */
    function lockDeed(uint256 deedId, uint256 lockDuration) 
        external 
        validDeed(deedId) 
        onlyDeedOwner(deedId)
        rateLimited
    {
        require(lockingEnabled, "Locking is disabled");
        require(lockDuration > 0 && lockDuration <= 365 days, "Invalid lock duration");

        OwnershipDeed storage deed = ownershipDeeds[deedId];
        deed.isLocked = true;
        deed.lockExpiry = block.timestamp + lockDuration;
    }

    /**
     * @dev Unlock deed with security checks
     */
    function unlockDeed(uint256 deedId) 
        external 
        validDeed(deedId) 
        onlyDeedOwner(deedId) 
    {
        OwnershipDeed storage deed = ownershipDeeds[deedId];
        require(deed.isLocked, "Deed is not locked");
        require(deed.lockExpiry <= block.timestamp, "Lock period not expired");

        deed.isLocked = false;
        deed.lockExpiry = 0;
    }

    // ============ TRANSFER REQUEST MANAGEMENT ============

    /**
     * @dev Create transfer request with security limits
     */
    function createTransferRequest(
        uint256 deedId,
        address to,
        uint256 proposedPrice,
        string memory transferReason
    ) external 
      validDeed(deedId)
      deedNotLocked(deedId)
      whenNotPaused
      whenRequestsEnabled
      rateLimited
      notBlacklisted(to)
      nonReentrant
      returns (uint256)
    {
        TrataTechSecurityEnhanced.validateAddress(to);
        require(to != msg.sender, "Cannot transfer to self");
        TrataTechSecurityEnhanced.validateString(transferReason);

        // Check request limits
        require(_pendingRequestCount[msg.sender] < maxTransferRequests, "Too many pending requests");

        // Count existing pending requests for this deed (with pagination to prevent DoS)
        uint256 pendingForDeed = _countPendingRequestsForDeed(deedId);
        require(pendingForDeed < ABSOLUTE_MAX_REQUESTS, "Too many pending requests for deed");

        uint256 requestId = _requestIds;
        _requestIds++;

        TransferRequest storage newRequest = transferRequests[requestId];
        newRequest.requestId = requestId;
        newRequest.deedId = deedId;
        newRequest.from = ownershipDeeds[deedId].owner;
        newRequest.to = to;
        newRequest.requestDate = block.timestamp;
        newRequest.proposedPrice = proposedPrice;
        newRequest.transferReason = transferReason;
        newRequest.status = TransferStatus.PENDING;
        newRequest.requester = msg.sender;
        newRequest.expiryDate = block.timestamp + transferApprovalPeriod;
        newRequest.isApproved = false;
        newRequest.approver = address(0);
        newRequest.isExecuted = false;

        _pendingRequestCount[msg.sender]++;

        emit TransferRequestCreated(requestId, deedId, msg.sender, to, proposedPrice);
        return requestId;
    }

    /**
     * @dev Execute approved transfer request with security checks
     */
    function executeTransferRequest(uint256 requestId, string memory ipfsCID) 
        external 
        payable
        whenNotPaused
        nonReentrant
    {
        TransferRequest storage request = transferRequests[requestId];

        require(request.requestId != 0, "Request does not exist");
        require(request.status == TransferStatus.APPROVED, "Request not approved");
        require(!request.isExecuted, "Request already executed");
        require(request.expiryDate > block.timestamp, "Request expired");
        require(request.requester == msg.sender, "Only requester can execute");

        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);

        uint256 deedId = request.deedId;
        OwnershipDeed storage deed = ownershipDeeds[deedId];

        // Verify deed is still valid and not locked
        require(deed.isValid, "Deed is invalid");
        require(!deed.isLocked || deed.lockExpiry <= block.timestamp, "Deed is locked");

        // Handle royalty payment first
        uint256 royaltyPaid = 0;
        if (request.proposedPrice > 0 && royaltiesEnabled && deedRoyalties[deedId].isActive) {
            royaltyPaid = _handleRoyaltyPayment(deedId, request.proposedPrice);
        }

        // Update states
        deed.previousOwner = request.from;
        deed.owner = request.to;
        deed.transferCount++;

        request.status = TransferStatus.EXECUTED;
        request.isExecuted = true;

        // Update mappings
        _removeDeedFromOwner(request.from, deedId);
        ownerToDeeds[request.to].push(deedId);
        _pendingRequestCount[request.requester]--;

        // Transfer NFT
        _transfer(request.from, request.to, deedId);

        totalTransfersCompleted++;

        emit OwnershipDeedTransferred(
            deedId, 
            request.from, 
            request.to, 
            request.proposedPrice, 
            TransferType.SECONDARY_SALE
        );
    }

    // ============ ROYALTY MANAGEMENT WITH SECURITY ============

    /**
     * @dev Set royalty with limits and validation
     */
    function setRoyalty(
        uint256 deedId,
        address recipient,
        uint256 percentage,
        uint256 maxAmount
    ) external 
      validDeed(deedId) 
      onlyDeedOwner(deedId) 
    {
        TrataTechSecurityEnhanced.validateAddress(recipient);
        TrataTechSecurityEnhanced.validatePercentage(percentage);
        require(percentage <= MAX_ROYALTY_PERCENTAGE, "Royalty too high");

        RoyaltyInfo storage royalty = deedRoyalties[deedId];
        royalty.recipient = recipient;
        royalty.percentage = percentage;
        royalty.maxAmount = maxAmount;
        royalty.isActive = true;
        royalty.totalCollected = 0;
    }

    // ============ ADMIN FUNCTIONS WITH SECURITY ============

    /**
     * @dev Blacklist address for security
     */
    function blacklistAddress(address addr, string memory reason) 
        external 
        onlyRole(ADMIN_ROLE) 
    {
        TrataTechSecurityEnhanced.validateAddress(addr);
        TrataTechSecurityEnhanced.validateString(reason);

        _blacklistedAddresses[addr] = true;
        emit AddressBlacklisted(addr, reason);
    }

    /**
     * @dev Set secure limits
     */
    function setSecurityLimits(
        uint256 newMaxRequests,
        uint256 newMaxDailyTransfers,
        uint256 newApprovalPeriod
    ) external onlyRole(ADMIN_ROLE) {
        require(newMaxRequests <= ABSOLUTE_MAX_REQUESTS, "Max requests too high");
        require(newApprovalPeriod >= 1 days && newApprovalPeriod <= 30 days, "Invalid approval period");

        maxTransferRequests = newMaxRequests;
        maxDailyTransfers = newMaxDailyTransfers;
        transferApprovalPeriod = newApprovalPeriod;
    }

    /**
     * @dev Circuit breaker controls
     */
    function toggleTransfers() external onlyRole(ADMIN_ROLE) {
        transfersEnabled = !transfersEnabled;
        emit CircuitBreakerActivated("transfers", msg.sender);
    }

    function toggleRoyalties() external onlyRole(ADMIN_ROLE) {
        royaltiesEnabled = !royaltiesEnabled;
        emit CircuitBreakerActivated("royalties", msg.sender);
    }

    function toggleRequests() external onlyRole(ADMIN_ROLE) {
        requestsEnabled = !requestsEnabled;
        emit CircuitBreakerActivated("requests", msg.sender);
    }

    /**
     * @dev Emergency withdrawal with security
     */
    function withdrawFees(address payable recipient) 
        external 
        onlyRole(ADMIN_ROLE) 
        nonReentrant 
    {
        TrataTechSecurityEnhanced.validateAddress(recipient);

        uint256 balance = address(this).balance;
        require(balance > 0, "No fees to withdraw");

        bool success = TrataTechSecurityEnhanced.safeTransferETH(recipient, balance);
        require(success, "Transfer failed");

        totalFeesCollected += balance;
    }

    // ============ INTERNAL HELPER FUNCTIONS ============

    /**
     * @dev Handle royalty payment with reentrancy protection
     */
    function _handleRoyaltyPayment(uint256 deedId, uint256 transferPrice) 
        internal 
        returns (uint256) 
    {
        RoyaltyInfo storage royalty = deedRoyalties[deedId];

        uint256 royaltyAmount = TrataTechSecurityEnhanced.calculateFee(transferPrice, royalty.percentage);

        // Apply maximum royalty limit if set
        if (royalty.maxAmount > 0 && royaltyAmount > royalty.maxAmount) {
            royaltyAmount = royalty.maxAmount;
        }

        if (royaltyAmount > 0) {
            // Use secure transfer
            bool success = TrataTechSecurityEnhanced.safeTransferETH(royalty.recipient, royaltyAmount);
            require(success, "Royalty transfer failed");

            royalty.totalCollected += royaltyAmount;

            emit RoyaltyPaid(deedId, royalty.recipient, royaltyAmount, transferPrice);
        }

        return royaltyAmount;
    }

    /**
     * @dev Remove deed from owner's list securely
     */
    function _removeDeedFromOwner(address owner, uint256 deedId) internal {
        uint256[] storage deeds = ownerToDeeds[owner];
        uint256 length = deeds.length;

        for (uint256 i = 0; i < length; i++) {
            if (deeds[i] == deedId) {
                deeds[i] = deeds[length - 1];
                deeds.pop();
                break;
            }
        }
    }

    /**
     * @dev Count pending requests for deed with limit to prevent DoS
     */
    function _countPendingRequestsForDeed(uint256 deedId) internal view returns (uint256) {
        uint256 count = 0;
        uint256 maxCheck = _requestIds > 100 ? _requestIds - 100 : 1; // Only check last 100 requests

        for (uint256 i = _requestIds - 1; i >= maxCheck && count < ABSOLUTE_MAX_REQUESTS; i--) {
            TransferRequest storage request = transferRequests[i];
            if (request.deedId == deedId && request.status == TransferStatus.PENDING) {
                count++;
            }
        }

        return count;
    }

    // ============ VIEW FUNCTIONS WITH PAGINATION ============

    /**
     * @dev Get pending transfer requests with pagination
     */
    function getPendingTransferRequestsPaginated(
        uint256 deedId,
        uint256 offset,
        uint256 limit
    ) external view returns (uint256[] memory) {
        require(limit <= 20, "Limit too high"); // Prevent large responses

        uint256[] memory results = new uint256[](limit);
        uint256 found = 0;
        uint256 checked = 0;

        // Start from most recent requests
        for (uint256 i = _requestIds - 1; i >= 1 && found < limit && checked < offset + limit * 2; i--) {
            TransferRequest storage request = transferRequests[i];

            if (request.deedId == deedId && request.status == TransferStatus.PENDING) {
                if (checked >= offset) {
                    results[found] = i;
                    found++;
                }
                checked++;
            }
        }

        // Resize array to actual results
        uint256[] memory finalResults = new uint256[](found);
        for (uint256 i = 0; i < found; i++) {
            finalResults[i] = results[i];
        }

        return finalResults;
    }

    /**
     * @dev Get security metrics
     */
    function getSecurityMetrics() external view returns (
        uint256 totalDeeds,
        uint256 totalTransfers,
        uint256 totalRoyalties,
        uint256 totalFees,
        bool transfersActive,
        bool royaltiesActive,
        bool requestsActive
    ) {
        return (
            totalDeedsCreated,
            totalTransfersCompleted,
            totalRoyaltiesPaid,
            totalFeesCollected,
            transfersEnabled,
            royaltiesEnabled,
            requestsEnabled
        );
    }

    // ============ INTERFACE SUPPORT ============

    function supportsInterface(bytes4 interfaceId) 
        public 
        view 
        override(ERC721, AccessControl) 
        returns (bool) 
    {
        return super.supportsInterface(interfaceId);
    }

    // ============ RECEIVE FUNCTION ============

    receive() external payable {
        // Contract can receive ETH for fees and royalties
    }

    // ============ OVERRIDE FUNCTIONS FOR ERC2771Context ============

    function _msgSender() internal view override(Context, ERC2771Context) returns (address) {
        return ERC2771Context._msgSender();
    }

    function _msgData() internal view override(Context, ERC2771Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength() internal view override(Context, ERC2771Context) returns (uint256) {
        return ERC2771Context._contextSuffixLength();
    }
}

contracts/TrataTechProductPassport_Fixed.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import "./TrataTechSecurityEnhanced.sol";

/**
 * @title TrataTechProductPassport_Fixed
 * @dev SECURITY-ENHANCED Product Passport Contract with comprehensive security fixes
 * @dev Fixed all critical vulnerabilities: access control, fee handling, brand registration
 */
contract TrataTechProductPassport_Fixed is AccessControl, ERC2771Context, Pausable, ReentrancyGuard {

    using ECDSA for bytes32;
    using TrataTechSecurityEnhanced for string;
    using TrataTechSecurityEnhanced for address;
    using TrataTechSecurityEnhanced for uint256;

    // ============ ROLES ============

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant BRAND_ROLE = keccak256("BRAND_ROLE");
    bytes32 public constant MANUFACTURER_ROLE = keccak256("MANUFACTURER_ROLE");
    bytes32 public constant CERTIFIER_ROLE = keccak256("CERTIFIER_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant BRAND_APPROVER_ROLE = keccak256("BRAND_APPROVER_ROLE");

    // ============ STRUCTS ============

    struct ProductPassport {
        uint256 passportId;
        string serialNumber;
        string brandId;
        string productName;
        string productDescription;
        string materials;
        string manufacturingLocation;
        uint256 manufacturingDate;
        uint256 creationTimestamp;
        string ipfsCID;
        string metadataHash;
        bool isValid;
        bool isRecalled;
        address creator;
        address brandAddress;
        mapping(string => string) additionalAttributes;
        string[] attributeKeys;
        uint256 updateCount; // Track number of updates
        bool isLocked; // Prevent unauthorized changes
    }

    struct Brand {
        string brandId;
        string brandName;
        string brandDescription;
        string ipfsCID;
        bool isActive;
        bool isVerified;
        bool isPending; // Pending approval
        address brandAddress;
        uint256 registrationDate;
        string[] authorizedCountries;
        mapping(string => bool) countryAuthorizations;
        uint256 passportCount; // Number of passports created
        uint256 registrationFee; // Fee paid during registration
        address approver; // Who approved this brand
        uint256 approvalDate;
    }

    struct ManufacturingCertificate {
        uint256 certificateId;
        uint256 passportId;
        string certificateType;
        string certificateNumber;
        string issuingAuthority;
        uint256 issueDate;
        uint256 expiryDate;
        string ipfsCID;
        bool isValid;
        address issuer;
        bool isExpired; // Auto-calculated expiry status
        uint256 validationCount; // Track validations
    }

    // ============ STATE VARIABLES ============

    uint256 private _passportIds;
    uint256 private _certificateIds;

    // Core mappings
    mapping(uint256 => ProductPassport) public productPassports;
    mapping(string => Brand) public brands;
    mapping(uint256 => ManufacturingCertificate) public certificates;
    mapping(string => uint256) public serialNumberToPassportId;

    // Brand management with security
    mapping(address => string[]) public ownerToBrands; // Track brands per owner
    mapping(string => address) public brandIdToAddress;
    mapping(address => string) public addressToBrandId;
    mapping(string => uint256[]) public brandToPassports; // Track passports per brand
    mapping(uint256 => uint256[]) public passportToCertificates; // Track certificates per passport

    // Security mappings
    mapping(address => uint256) private _lastActionTime; // Rate limiting
    mapping(address => uint256) private _dailyActionCount; // Daily limits
    mapping(address => uint256) private _lastResetTime;
    mapping(address => bool) private _blacklistedAddresses;
    mapping(string => bool) private _reservedBrandIds; // Prevent squatting

    // Fee structure with security limits
    uint256 public passportCreationFee;
    uint256 public certificateCreationFee;
    uint256 public brandRegistrationFee;
    uint256 public brandVerificationFee;
    uint256 public constant MAX_FEE = 1 ether;
    uint256 public constant DAILY_ACTION_LIMIT = 50;
    uint256 public constant FEE_DENOMINATOR = 10000;

    // Circuit breakers and controls
    bool public brandRegistrationEnabled;
    bool public passportCreationEnabled;
    bool public certificateCreationEnabled;
    bool public brandApprovalRequired; // Require admin approval for new brands
    bool public automaticVerification; // Auto-verify upon payment of verification fee

    // Treasury and fee management
    address public treasury;
    address public feeCollector;
    bool public treasuryLocked;

    // Security tracking
    uint256 public totalBrandsRegistered;
    uint256 public totalBrandsVerified;
    uint256 public totalPassportsCreated;
    uint256 public totalCertificatesCreated;
    uint256 public totalFeesCollected;

    // ============ EVENTS ============

    event BrandRegistered(
        string indexed brandId,
        string brandName,
        address indexed brandAddress,
        string ipfsCID,
        bool requiresApproval,
        uint256 fee
    );

    event BrandApproved(
        string indexed brandId,
        address indexed approver,
        uint256 approvalDate
    );

    event BrandVerified(
        string indexed brandId,
        address indexed verifier,
        uint256 verificationFee
    );

    event ProductPassportCreated(
        uint256 indexed passportId,
        string serialNumber,
        string brandId,
        string productName,
        string ipfsCID,
        address indexed creator
    );

    event ManufacturingCertificateCreated(
        uint256 indexed certificateId,
        uint256 indexed passportId,
        string certificateType,
        string certificateNumber,
        string ipfsCID,
        address indexed issuer
    );

    event SecurityViolationDetected(string violationType, address violator);
    event CircuitBreakerActivated(string feature, address activatedBy);
    event BrandIdReserved(string brandId, address reservedBy);
    event DailyLimitExceeded(address user, uint256 attempts);
    event TreasuryUpdated(address oldTreasury, address newTreasury);

    // ============ MODIFIERS ============

    modifier rateLimited() {
        TrataTechSecurityEnhanced.checkRateLimit(_lastActionTime[msg.sender]);
        TrataTechSecurityEnhanced.updateRateLimit(msg.sender, _lastActionTime);
        _;
    }

    modifier dailyLimited() {
        _checkDailyLimit();
        _updateDailyCounter();
        _;
    }

    modifier notBlacklisted(address addr) {
        require(!_blacklistedAddresses[addr], "Address is blacklisted");
        _;
    }

    modifier validPassport(uint256 passportId) {
        require(productPassports[passportId].passportId != 0, "Passport does not exist");
        require(productPassports[passportId].isValid, "Passport is invalid");
        require(!productPassports[passportId].isRecalled, "Passport is recalled");
        _;
    }

    modifier validBrand(string memory brandId) {
        require(bytes(brands[brandId].brandId).length > 0, "Brand does not exist");
        require(brands[brandId].isActive, "Brand is not active");
        _;
    }

    modifier passportNotLocked(uint256 passportId) {
        require(!productPassports[passportId].isLocked, "Passport is locked");
        _;
    }

    modifier whenBrandRegistrationEnabled() {
        require(brandRegistrationEnabled, "Brand registration is disabled");
        _;
    }

    modifier whenPassportCreationEnabled() {
        require(passportCreationEnabled, "Passport creation is disabled");
        _;
    }

    modifier treasuryNotLocked() {
        require(!treasuryLocked, "Treasury operations are locked");
        _;
    }

    // ============ CONSTRUCTOR ============

    constructor(address _treasury, address _feeCollector, address trustedForwarder) 
        ERC2771Context(trustedForwarder) {
        TrataTechSecurityEnhanced.validateAddress(_treasury);
        TrataTechSecurityEnhanced.validateAddress(_feeCollector);

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(BRAND_APPROVER_ROLE, msg.sender);

        treasury = _treasury;
        feeCollector = _feeCollector;

        // Set secure initial fees
        passportCreationFee = 0.01 ether;
        certificateCreationFee = 0.005 ether;
        brandRegistrationFee = 0.02 ether;
        brandVerificationFee = 0.01 ether;

        // Enable features with security defaults
        brandRegistrationEnabled = true;
        passportCreationEnabled = true;
        certificateCreationEnabled = true;
        brandApprovalRequired = true; // Require approval by default
        automaticVerification = false; // Manual verification by default

        _passportIds = 1;
        _certificateIds = 1;
    }

    // ============ BRAND MANAGEMENT WITH SECURITY ============

    /**
     * @dev Register a new brand with approval workflow and security checks
     */
    function registerBrand(
        string memory brandId,
        string memory brandName,
        string memory brandDescription,
        string memory ipfsCID,
        string[] memory authorizedCountries
    ) external 
      payable
      whenNotPaused
      whenBrandRegistrationEnabled
      rateLimited
      dailyLimited
      notBlacklisted(msg.sender)
      nonReentrant
    {
        // Process payment with automatic refund
        TrataTechSecurityEnhanced.processPaymentWithRefund(brandRegistrationFee);

        // Validate all inputs
        TrataTechSecurityEnhanced.validateString(brandId);
        TrataTechSecurityEnhanced.validateString(brandName);
        TrataTechSecurityEnhanced.validateString(brandDescription);
        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);
        TrataTechSecurityEnhanced.validateArraySize(authorizedCountries.length);

        require(bytes(brands[brandId].brandId).length == 0, "Brand ID already exists");
        require(!_reservedBrandIds[brandId], "Brand ID is reserved");
        require(brandIdToAddress[brandId] == address(0), "Brand ID already registered");

        // Validate authorized countries
        for (uint256 i = 0; i < authorizedCountries.length; i++) {
            TrataTechSecurityEnhanced.validateString(authorizedCountries[i]);
        }

        Brand storage newBrand = brands[brandId];
        newBrand.brandId = brandId;
        newBrand.brandName = brandName;
        newBrand.brandDescription = brandDescription;
        newBrand.ipfsCID = ipfsCID;
        newBrand.isActive = true;
        newBrand.isVerified = false;
        newBrand.isPending = brandApprovalRequired;
        newBrand.brandAddress = msg.sender;
        newBrand.registrationDate = block.timestamp;
        newBrand.authorizedCountries = authorizedCountries;
        newBrand.registrationFee = brandRegistrationFee;

        // Set country authorizations
        for (uint256 i = 0; i < authorizedCountries.length; i++) {
            newBrand.countryAuthorizations[authorizedCountries[i]] = true;
        }

        // Update mappings
        brandIdToAddress[brandId] = msg.sender;
        addressToBrandId[msg.sender] = brandId;
        ownerToBrands[msg.sender].push(brandId);

        // If approval not required, grant brand role immediately
        if (!brandApprovalRequired) {
            _grantRole(BRAND_ROLE, msg.sender);
            newBrand.isPending = false;
        }

        totalBrandsRegistered++;
        totalFeesCollected += brandRegistrationFee;

        emit BrandRegistered(
            brandId, 
            brandName, 
            msg.sender, 
            ipfsCID, 
            brandApprovalRequired,
            brandRegistrationFee
        );
    }

    /**
     * @dev Approve a pending brand (admin only)
     */
    function approveBrand(string memory brandId) 
        external 
        onlyRole(BRAND_APPROVER_ROLE)
        validBrand(brandId)
    {
        Brand storage brand = brands[brandId];
        require(brand.isPending, "Brand is not pending approval");

        brand.isPending = false;
        brand.approver = msg.sender;
        brand.approvalDate = block.timestamp;

        // Grant brand role to brand owner
        _grantRole(BRAND_ROLE, brand.brandAddress);

        emit BrandApproved(brandId, msg.sender, block.timestamp);
    }

    /**
     * @dev Verify a brand with fee payment or admin action
     */
    function verifyBrand(string memory brandId) 
        external 
        payable
        validBrand(brandId)
        nonReentrant
    {
        Brand storage brand = brands[brandId];
        require(!brand.isVerified, "Brand already verified");
        require(!brand.isPending, "Brand pending approval");

        bool isAdmin = hasRole(ADMIN_ROLE, msg.sender);
        bool isBrandOwner = brand.brandAddress == msg.sender;

        if (isAdmin) {
            // Admin can verify without payment
            if (msg.value > 0) {
                // Refund any payment sent by admin
                (bool success, ) = payable(msg.sender).call{value: msg.value}("");
                require(success, "Refund failed");
            }
        } else if (isBrandOwner && automaticVerification) {
            // Brand owner can pay for automatic verification
            TrataTechSecurityEnhanced.processPaymentWithRefund(brandVerificationFee);
            totalFeesCollected += brandVerificationFee;
        } else {
            revert("Not authorized to verify brand");
        }

        brand.isVerified = true;
        totalBrandsVerified++;

        emit BrandVerified(brandId, msg.sender, msg.value);
    }

    /**
     * @dev Reserve brand ID to prevent squatting (admin only)
     */
    function reserveBrandId(string memory brandId) 
        external 
        onlyRole(ADMIN_ROLE) 
    {
        TrataTechSecurityEnhanced.validateString(brandId);
        require(bytes(brands[brandId].brandId).length == 0, "Brand ID already exists");

        _reservedBrandIds[brandId] = true;
        emit BrandIdReserved(brandId, msg.sender);
    }

    // ============ PRODUCT PASSPORT MANAGEMENT ============

    /**
     * @dev Create a new product passport with enhanced security
     */
    function createProductPassport(
        string memory serialNumber,
        string memory brandId,
        string memory productName,
        string memory productDescription,
        string memory materials,
        string memory manufacturingLocation,
        uint256 manufacturingDate,
        string memory ipfsCID,
        string memory metadataHash
    ) external 
      payable
      whenNotPaused
      whenPassportCreationEnabled
      rateLimited
      dailyLimited
      validBrand(brandId)
      notBlacklisted(msg.sender)
      nonReentrant
      returns (uint256)
    {
        // Check authorization
        bool isAuthorized = hasRole(BRAND_ROLE, msg.sender) || 
                           brands[brandId].brandAddress == msg.sender ||
                           hasRole(MANUFACTURER_ROLE, msg.sender);
        require(isAuthorized, "Not authorized for this brand");

        Brand storage brand = brands[brandId];
        require(!brand.isPending, "Brand is pending approval");

        // Process payment with automatic refund
        TrataTechSecurityEnhanced.processPaymentWithRefund(passportCreationFee);

        // Validate all inputs
        TrataTechSecurityEnhanced.validateString(serialNumber);
        TrataTechSecurityEnhanced.validateString(productName);
        TrataTechSecurityEnhanced.validateString(productDescription);
        TrataTechSecurityEnhanced.validateString(materials);
        TrataTechSecurityEnhanced.validateString(manufacturingLocation);
        TrataTechSecurityEnhanced.validateTimestamp(manufacturingDate);
        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);
        TrataTechSecurityEnhanced.validateString(metadataHash);

        require(serialNumberToPassportId[serialNumber] == 0, "Serial number already exists");

        uint256 passportId = _passportIds;
        _passportIds++;

        ProductPassport storage newPassport = productPassports[passportId];
        newPassport.passportId = passportId;
        newPassport.serialNumber = serialNumber;
        newPassport.brandId = brandId;
        newPassport.productName = productName;
        newPassport.productDescription = productDescription;
        newPassport.materials = materials;
        newPassport.manufacturingLocation = manufacturingLocation;
        newPassport.manufacturingDate = manufacturingDate;
        newPassport.creationTimestamp = block.timestamp;
        newPassport.ipfsCID = ipfsCID;
        newPassport.metadataHash = metadataHash;
        newPassport.isValid = true;
        newPassport.isRecalled = false;
        newPassport.creator = msg.sender;
        newPassport.brandAddress = brandIdToAddress[brandId];
        newPassport.updateCount = 0;
        newPassport.isLocked = false;

        // Update mappings
        serialNumberToPassportId[serialNumber] = passportId;
        brandToPassports[brandId].push(passportId);
        brand.passportCount++;

        totalPassportsCreated++;
        totalFeesCollected += passportCreationFee;

        emit ProductPassportCreated(
            passportId,
            serialNumber,
            brandId,
            productName,
            ipfsCID,
            msg.sender
        );

        return passportId;
    }

    /**
     * @dev Update product passport metadata with security checks
     */
    function updateProductPassport(
        uint256 passportId,
        string memory ipfsCID,
        string memory metadataHash
    ) external 
      validPassport(passportId) 
      passportNotLocked(passportId)
      rateLimited
      whenNotPaused 
    {
        ProductPassport storage passport = productPassports[passportId];

        // Check authorization
        bool isAuthorized = msg.sender == passport.creator || 
                           msg.sender == passport.brandAddress || 
                           hasRole(ADMIN_ROLE, msg.sender) ||
                           hasRole(OPERATOR_ROLE, msg.sender);
        require(isAuthorized, "Not authorized to update passport");

        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);
        TrataTechSecurityEnhanced.validateString(metadataHash);

        passport.ipfsCID = ipfsCID;
        passport.metadataHash = metadataHash;
        passport.updateCount++;
    }

    /**
     * @dev Lock passport to prevent further modifications
     */
    function lockPassport(uint256 passportId) 
        external 
        validPassport(passportId)
        onlyRole(ADMIN_ROLE)
    {
        productPassports[passportId].isLocked = true;
    }

    // ============ CERTIFICATE MANAGEMENT ============

    /**
     * @dev Create manufacturing certificate with security
     */
    function createManufacturingCertificate(
        uint256 passportId,
        string memory certificateType,
        string memory certificateNumber,
        string memory issuingAuthority,
        uint256 issueDate,
        uint256 expiryDate,
        string memory ipfsCID
    ) external 
      payable
      validPassport(passportId)
      whenNotPaused
      rateLimited
      nonReentrant
      onlyRole(CERTIFIER_ROLE)
      returns (uint256)
    {
        TrataTechSecurityEnhanced.processPaymentWithRefund(certificateCreationFee);

        // Validate inputs
        TrataTechSecurityEnhanced.validateString(certificateType);
        TrataTechSecurityEnhanced.validateString(certificateNumber);
        TrataTechSecurityEnhanced.validateString(issuingAuthority);
        TrataTechSecurityEnhanced.validateDateRange(issueDate, expiryDate);
        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);

        uint256 certificateId = _certificateIds;
        _certificateIds++;

        ManufacturingCertificate storage newCert = certificates[certificateId];
        newCert.certificateId = certificateId;
        newCert.passportId = passportId;
        newCert.certificateType = certificateType;
        newCert.certificateNumber = certificateNumber;
        newCert.issuingAuthority = issuingAuthority;
        newCert.issueDate = issueDate;
        newCert.expiryDate = expiryDate;
        newCert.ipfsCID = ipfsCID;
        newCert.isValid = true;
        newCert.issuer = msg.sender;
        newCert.isExpired = block.timestamp > expiryDate;
        newCert.validationCount = 0;

        // Update mappings
        passportToCertificates[passportId].push(certificateId);

        totalCertificatesCreated++;
        totalFeesCollected += certificateCreationFee;

        emit ManufacturingCertificateCreated(
            certificateId,
            passportId,
            certificateType,
            certificateNumber,
            ipfsCID,
            msg.sender
        );

        return certificateId;
    }

    // ============ ADMIN FUNCTIONS WITH SECURITY ============

    /**
     * @dev Update fees with validation
     */
    function updateFees(
        uint256 newPassportFee,
        uint256 newCertificateFee,
        uint256 newBrandRegistrationFee,
        uint256 newBrandVerificationFee
    ) external onlyRole(ADMIN_ROLE) {
        require(newPassportFee <= MAX_FEE, "Passport fee too high");
        require(newCertificateFee <= MAX_FEE, "Certificate fee too high");
        require(newBrandRegistrationFee <= MAX_FEE, "Brand registration fee too high");
        require(newBrandVerificationFee <= MAX_FEE, "Brand verification fee too high");

        passportCreationFee = newPassportFee;
        certificateCreationFee = newCertificateFee;
        brandRegistrationFee = newBrandRegistrationFee;
        brandVerificationFee = newBrandVerificationFee;
    }

    /**
     * @dev Blacklist address for security
     */
    function blacklistAddress(address addr, bool status) 
        external 
        onlyRole(ADMIN_ROLE) 
    {
        TrataTechSecurityEnhanced.validateAddress(addr);
        _blacklistedAddresses[addr] = status;
    }

    /**
     * @dev Circuit breaker controls
     */
    function toggleBrandRegistration() external onlyRole(ADMIN_ROLE) {
        brandRegistrationEnabled = !brandRegistrationEnabled;
        emit CircuitBreakerActivated("brand_registration", msg.sender);
    }

    function togglePassportCreation() external onlyRole(ADMIN_ROLE) {
        passportCreationEnabled = !passportCreationEnabled;
        emit CircuitBreakerActivated("passport_creation", msg.sender);
    }

    function toggleCertificateCreation() external onlyRole(ADMIN_ROLE) {
        certificateCreationEnabled = !certificateCreationEnabled;
        emit CircuitBreakerActivated("certificate_creation", msg.sender);
    }

    function toggleApprovalRequired() external onlyRole(ADMIN_ROLE) {
        brandApprovalRequired = !brandApprovalRequired;
    }

    function toggleAutomaticVerification() external onlyRole(ADMIN_ROLE) {
        automaticVerification = !automaticVerification;
    }

    /**
     * @dev Set treasury with security
     */
    function setTreasury(address newTreasury) 
        external 
        onlyRole(ADMIN_ROLE) 
        treasuryNotLocked 
    {
        TrataTechSecurityEnhanced.validateAddress(newTreasury);

        address oldTreasury = treasury;
        treasury = newTreasury;

        emit TreasuryUpdated(oldTreasury, newTreasury);
    }

    /**
     * @dev Secure fee withdrawal
     */
    function withdrawFees() 
        external 
        onlyRole(ADMIN_ROLE) 
        treasuryNotLocked
        nonReentrant 
    {
        uint256 balance = address(this).balance;
        require(balance > 0, "No fees to withdraw");

        bool success = TrataTechSecurityEnhanced.safeTransferETH(treasury, balance);
        require(success, "Transfer to treasury failed");
    }

    /**
     * @dev Emergency pause
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    // ============ INTERNAL HELPER FUNCTIONS ============

    /**
     * @dev Check daily action limits
     */
    function _checkDailyLimit() internal view {
        if (block.timestamp - _lastResetTime[msg.sender] >= 1 days) {
            return; // Reset period passed
        }

        require(_dailyActionCount[msg.sender] < DAILY_ACTION_LIMIT, "Daily limit exceeded");
    }

    /**
     * @dev Update daily action counter
     */
    function _updateDailyCounter() internal {
        if (block.timestamp - _lastResetTime[msg.sender] >= 1 days) {
            _dailyActionCount[msg.sender] = 1;
            _lastResetTime[msg.sender] = block.timestamp;
        } else {
            _dailyActionCount[msg.sender]++;
        }

        if (_dailyActionCount[msg.sender] >= DAILY_ACTION_LIMIT) {
            emit DailyLimitExceeded(msg.sender, _dailyActionCount[msg.sender]);
        }
    }

    // ============ VIEW FUNCTIONS ============

    /**
     * @dev Get brand details with security info
     */
    function getBrandDetailsWithSecurity(string memory brandId) 
        external 
        view 
        returns (
            string memory name,
            bool isActive,
            bool isVerified,
            bool isPending,
            address brandAddress,
            uint256 passportCount,
            uint256 registrationDate
        ) 
    {
        Brand storage brand = brands[brandId];
        return (
            brand.brandName,
            brand.isActive,
            brand.isVerified,
            brand.isPending,
            brand.brandAddress,
            brand.passportCount,
            brand.registrationDate
        );
    }

    /**
     * @dev Get security metrics
     */
    function getSecurityMetrics() external view returns (
        uint256 totalBrands,
        uint256 totalVerified,
        uint256 totalPassports,
        uint256 totalCertificates,
        uint256 totalFees,
        bool brandRegEnabled,
        bool passportEnabled,
        bool certEnabled,
        bool approvalRequired
    ) {
        return (
            totalBrandsRegistered,
            totalBrandsVerified,
            totalPassportsCreated,
            totalCertificatesCreated,
            totalFeesCollected,
            brandRegistrationEnabled,
            passportCreationEnabled,
            certificateCreationEnabled,
            brandApprovalRequired
        );
    }

    /**
     * @dev Check if address is blacklisted
     */
    function isBlacklisted(address addr) external view returns (bool) {
        return _blacklistedAddresses[addr];
    }

    /**
     * @dev Check user action status
     */
    function getUserActionStatus(address user) external view returns (
        uint256 lastActionTime,
        uint256 dailyCount,
        bool canAct
    ) {
        return (
            _lastActionTime[user],
            _dailyActionCount[user],
            block.timestamp >= _lastActionTime[user] + TrataTechSecurityEnhanced.RATE_LIMIT_DURATION &&
            _dailyActionCount[user] < DAILY_ACTION_LIMIT
        );
    }

    // ============ RECEIVE FUNCTION ============

    receive() external payable {
        // Contract can receive ETH for fees
    }

    // ============ OVERRIDE FUNCTIONS FOR ERC2771Context ============

    function _msgSender() internal view override(Context, ERC2771Context) returns (address) {
        return ERC2771Context._msgSender();
    }

    function _msgData() internal view override(Context, ERC2771Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength() internal view override(Context, ERC2771Context) returns (uint256) {
        return ERC2771Context._contextSuffixLength();
    }
}

contracts/TrataTechProductPassportUpgrad.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/metatx/ERC2771ContextUpgradeable.sol";
import "./TrataTechSecurityEnhanced.sol";

/**
 * @title TrataTechProductPassportUpgradeable_Fixed
 * @dev SECURITY-ENHANCED Upgradeable contract for managing digital product passports
 * @dev Fixed all critical vulnerabilities: storage safety, fee handling, access control
 */
contract TrataTechProductPassportUpgradeable_Fixed is 
    Initializable,
    AccessControlUpgradeable,
    ERC2771ContextUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable
{
    using TrataTechSecurityEnhanced for string;
    using TrataTechSecurityEnhanced for address;
    using TrataTechSecurityEnhanced for uint256;

    // ============ ROLES ============

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant BRAND_ROLE = keccak256("BRAND_ROLE");
    bytes32 public constant MANUFACTURER_ROLE = keccak256("MANUFACTURER_ROLE");
    bytes32 public constant CERTIFIER_ROLE = keccak256("CERTIFIER_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    // ============ STRUCTS ============

    struct ProductPassport {
        uint256 id;
        string serialNumber;
        string brandId;
        string productName;
        string productDescription;
        string materials;
        string manufacturingLocation;
        uint256 manufacturingDate;
        string ipfsCID;
        bytes32 metadataHash;
        string[] additionalAttributes;
        bool isValid;
        uint256 createdAt;
        uint256 updatedAt;
        address creator;
        bool isLocked; // Security enhancement
        uint256 lockExpiry;
    }

    struct Brand {
        string id;
        string name;
        string description;
        string ipfsCID;
        string[] authorizedCountries;
        bool isVerified;
        bool isActive;
        uint256 registrationFee;
        uint256 createdAt;
        address brandOwner;
        uint256 passportCount; // Track number of passports
        bool requiresVerification; // Security enhancement
    }

    struct ManufacturingCertificate {
        uint256 id;
        uint256 passportId;
        string certificateType;
        string certificateNumber;
        string issuingAuthority;
        uint256 issueDate;
        uint256 expiryDate;
        string ipfsCID;
        bool isValid;
        uint256 createdAt;
        address issuer;
        bool isExpired; // Auto-expiry tracking
    }

    // ============ STATE VARIABLES ============

    uint256 private _passportIds;
    uint256 private _certificateIds;

    // Brand management with security enhancements
    mapping(string => Brand) public brands;
    mapping(address => string[]) public ownerToBrands; // Track brands per owner
    mapping(string => uint256[]) public brandPassports;

    // Product passport management
    mapping(uint256 => ProductPassport) public productPassports;
    mapping(string => uint256) public serialNumberToPassportId;
    mapping(address => uint256[]) public creatorPassports; // Track passports per creator

    // Manufacturing certificate management
    mapping(uint256 => ManufacturingCertificate) public certificates;
    mapping(uint256 => uint256[]) public passportCertificates;

    // Security enhancements
    mapping(address => uint256) private _lastActionTime; // Rate limiting
    mapping(address => uint256) private _dailyActionCount; // Daily limits
    mapping(address => uint256) private _lastResetTime;

    // Fee management with security
    uint256 public brandRegistrationFee;
    uint256 public passportCreationFee;
    uint256 public certificateCreationFee;
    uint256 public platformFeePercentage;
    uint256 public constant MAX_FEE = 1 ether; // Maximum fee limit
    uint256 public constant DAILY_ACTION_LIMIT = 100; // Anti-spam

    // Multi-sig treasury management
    address public treasury;
    address public feeCollector;
    bool public treasuryLocked;

    // Circuit breakers
    bool public brandRegistrationEnabled;
    bool public passportCreationEnabled;
    bool public certificateCreationEnabled;

    // Monitoring
    uint256 public totalBrandsCreated;
    uint256 public totalPassportsCreated;
    uint256 public totalCertificatesCreated;
    uint256 public totalFeesCollected;

    // ============ EVENTS ============

    event BrandRegistered(
        string indexed brandId, 
        string name, 
        address indexed registrant, 
        uint256 fee,
        bool requiresVerification
    );
    event BrandVerified(string indexed brandId, address indexed verifier);
    event ProductPassportCreated(
        uint256 indexed passportId, 
        string serialNumber, 
        string indexed brandId, 
        string ipfsCID,
        address indexed creator
    );
    event CertificateCreated(
        uint256 indexed certificateId,
        uint256 indexed passportId,
        string certificateType,
        uint256 expiryDate
    );
    event SecurityViolationDetected(string violationType, address violator);
    event CircuitBreakerActivated(string feature, address activatedBy);
    event TreasuryUpdated(address oldTreasury, address newTreasury);
    event DailyLimitExceeded(address user, uint256 attempts);

    // ============ MODIFIERS ============

    modifier rateLimited() {
        TrataTechSecurityEnhanced.checkRateLimit(_lastActionTime[msg.sender]);
        TrataTechSecurityEnhanced.updateRateLimit(msg.sender, _lastActionTime);
        _;
    }

    modifier dailyLimited() {
        _checkDailyLimit();
        _updateDailyCounter();
        _;
    }

    modifier validPassportId(uint256 passportId) {
        require(passportId > 0 && passportId <= _passportIds, "Invalid passport ID");
        require(productPassports[passportId].isValid, "Passport is invalid");
        _;
    }

    modifier notLocked(uint256 passportId) {
        ProductPassport storage passport = productPassports[passportId];
        require(!passport.isLocked || passport.lockExpiry < block.timestamp, "Passport is locked");
        _;
    }

    modifier whenBrandRegistrationEnabled() {
        require(brandRegistrationEnabled, "Brand registration is disabled");
        _;
    }

    modifier whenPassportCreationEnabled() {
        require(passportCreationEnabled, "Passport creation is disabled");
        _;
    }

    modifier treasuryNotLocked() {
        require(!treasuryLocked, "Treasury operations are locked");
        _;
    }

    // ============ INITIALIZATION ============

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(address trustedForwarder) ERC2771ContextUpgradeable(trustedForwarder) {
        _disableInitializers();
    }

    function initialize(
        address initialOwner,
        address _treasury,
        address _feeCollector
    ) public initializer {
        __AccessControl_init();
        __Pausable_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        TrataTechSecurityEnhanced.validateAddress(initialOwner);
        TrataTechSecurityEnhanced.validateAddress(_treasury);
        TrataTechSecurityEnhanced.validateAddress(_feeCollector);

        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        _grantRole(ADMIN_ROLE, initialOwner);
        _grantRole(UPGRADER_ROLE, initialOwner);

        // Set secure initial fees
        brandRegistrationFee = 0.01 ether;
        passportCreationFee = 0.02 ether;
        certificateCreationFee = 0.005 ether;
        platformFeePercentage = 250; // 2.5%

        treasury = _treasury;
        feeCollector = _feeCollector;

        // Enable all features initially
        brandRegistrationEnabled = true;
        passportCreationEnabled = true;
        certificateCreationEnabled = true;

        _passportIds = 1;
        _certificateIds = 1;
    }

    // ============ UUPS UPGRADEABLE WITH SECURITY ============

    function _authorizeUpgrade(address newImplementation) 
        internal 
        view
        override 
        onlyRole(UPGRADER_ROLE) 
    {
        TrataTechSecurityEnhanced.validateAddress(newImplementation);
        // Additional upgrade safety checks could be added here
    }

    // ============ BRAND MANAGEMENT WITH SECURITY ============

    /**
     * @dev Register a new brand with comprehensive security
     */
    function registerBrand(
        string memory brandId,
        string memory brandName,
        string memory brandDescription,
        string memory ipfsCID,
        string[] memory authorizedCountries,
        bool requiresVerification
    ) external 
      payable
      whenNotPaused
      whenBrandRegistrationEnabled
      rateLimited
      dailyLimited
      nonReentrant
    {
        // Process payment with automatic refund
        TrataTechSecurityEnhanced.processPaymentWithRefund(brandRegistrationFee);

        // Validate all inputs
        TrataTechSecurityEnhanced.validateString(brandId);
        TrataTechSecurityEnhanced.validateString(brandName);
        TrataTechSecurityEnhanced.validateString(brandDescription);
        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);
        TrataTechSecurityEnhanced.validateArraySize(authorizedCountries.length);

        require(bytes(brands[brandId].id).length == 0, "Brand ID already exists");

        // Validate authorized countries
        for (uint256 i = 0; i < authorizedCountries.length; i++) {
            TrataTechSecurityEnhanced.validateString(authorizedCountries[i]);
        }

        Brand storage newBrand = brands[brandId];
        newBrand.id = brandId;
        newBrand.name = brandName;
        newBrand.description = brandDescription;
        newBrand.ipfsCID = ipfsCID;
        newBrand.authorizedCountries = authorizedCountries;
        newBrand.isVerified = false;
        newBrand.isActive = true;
        newBrand.registrationFee = msg.value;
        newBrand.createdAt = block.timestamp;
        newBrand.brandOwner = msg.sender;
        newBrand.requiresVerification = requiresVerification;

        // Update tracking mappings
        ownerToBrands[msg.sender].push(brandId);
        totalBrandsCreated++;
        totalFeesCollected += brandRegistrationFee;

        // Grant brand role to registrant
        _grantRole(BRAND_ROLE, msg.sender);

        emit BrandRegistered(brandId, brandName, msg.sender, brandRegistrationFee, requiresVerification);
    }

    /**
     * @dev Verify a brand with enhanced security
     */
    function verifyBrand(string memory brandId) 
        external 
        onlyRole(ADMIN_ROLE) 
    {
        require(bytes(brands[brandId].id).length > 0, "Brand does not exist");
        require(!brands[brandId].isVerified, "Brand already verified");

        brands[brandId].isVerified = true;
        emit BrandVerified(brandId, msg.sender);
    }

    // ============ PRODUCT PASSPORT MANAGEMENT ============

    /**
     * @dev Create a product passport with security enhancements
     */
    function createProductPassport(
        string memory serialNumber,
        string memory brandId,
        string memory productName,
        string memory productDescription,
        string memory materials,
        string memory manufacturingLocation,
        uint256 manufacturingDate,
        string memory ipfsCID,
        bytes32 metadataHash,
        string[] memory additionalAttributes
    ) external 
      payable
      whenNotPaused
      whenPassportCreationEnabled
      rateLimited
      dailyLimited
      nonReentrant
      returns (uint256)
    {
        // Verify caller has brand role or is authorized for this brand
        require(
            hasRole(BRAND_ROLE, msg.sender) || 
            brands[brandId].brandOwner == msg.sender,
            "Not authorized for this brand"
        );

        // Process payment with automatic refund
        TrataTechSecurityEnhanced.processPaymentWithRefund(passportCreationFee);

        // Validate all inputs
        TrataTechSecurityEnhanced.validateString(serialNumber);
        TrataTechSecurityEnhanced.validateString(brandId);
        TrataTechSecurityEnhanced.validateString(productName);
        TrataTechSecurityEnhanced.validateString(productDescription);
        TrataTechSecurityEnhanced.validateString(materials);
        TrataTechSecurityEnhanced.validateString(manufacturingLocation);
        TrataTechSecurityEnhanced.validateTimestamp(manufacturingDate);
        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);
        TrataTechSecurityEnhanced.validateArraySize(additionalAttributes.length);

        require(bytes(brands[brandId].id).length > 0, "Brand does not exist");
        require(brands[brandId].isActive, "Brand is not active");
        require(serialNumberToPassportId[serialNumber] == 0, "Serial number already exists");

        // Check if brand requires verification
        if (brands[brandId].requiresVerification) {
            require(brands[brandId].isVerified, "Brand must be verified");
        }

        uint256 passportId = _passportIds;
        _passportIds++;

        ProductPassport storage newPassport = productPassports[passportId];
        newPassport.id = passportId;
        newPassport.serialNumber = serialNumber;
        newPassport.brandId = brandId;
        newPassport.productName = productName;
        newPassport.productDescription = productDescription;
        newPassport.materials = materials;
        newPassport.manufacturingLocation = manufacturingLocation;
        newPassport.manufacturingDate = manufacturingDate;
        newPassport.ipfsCID = ipfsCID;
        newPassport.metadataHash = metadataHash;
        newPassport.additionalAttributes = additionalAttributes;
        newPassport.isValid = true;
        newPassport.createdAt = block.timestamp;
        newPassport.updatedAt = block.timestamp;
        newPassport.creator = msg.sender;

        // Update mappings
        serialNumberToPassportId[serialNumber] = passportId;
        brandPassports[brandId].push(passportId);
        creatorPassports[msg.sender].push(passportId);
        brands[brandId].passportCount++;

        totalPassportsCreated++;
        totalFeesCollected += passportCreationFee;

        emit ProductPassportCreated(passportId, serialNumber, brandId, ipfsCID, msg.sender);
        return passportId;
    }

    /**
     * @dev Lock passport to prevent modifications
     */
    function lockPassport(uint256 passportId, uint256 lockDuration) 
        external
        validPassportId(passportId)
        onlyRole(ADMIN_ROLE)
    {
        require(lockDuration > 0 && lockDuration <= 365 days, "Invalid lock duration");

        ProductPassport storage passport = productPassports[passportId];
        passport.isLocked = true;
        passport.lockExpiry = block.timestamp + lockDuration;
    }

    // ============ CERTIFICATE MANAGEMENT ============

    /**
     * @dev Create manufacturing certificate with security
     */
    function createManufacturingCertificate(
        uint256 passportId,
        string memory certificateType,
        string memory certificateNumber,
        string memory issuingAuthority,
        uint256 issueDate,
        uint256 expiryDate,
        string memory ipfsCID
    ) external 
      payable
      validPassportId(passportId)
      whenNotPaused
      rateLimited
      nonReentrant
      onlyRole(CERTIFIER_ROLE)
      returns (uint256)
    {
        TrataTechSecurityEnhanced.processPaymentWithRefund(certificateCreationFee);

        // Validate inputs
        TrataTechSecurityEnhanced.validateString(certificateType);
        TrataTechSecurityEnhanced.validateString(certificateNumber);
        TrataTechSecurityEnhanced.validateString(issuingAuthority);
        TrataTechSecurityEnhanced.validateDateRange(issueDate, expiryDate);
        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);

        uint256 certificateId = _certificateIds;
        _certificateIds++;

        ManufacturingCertificate storage newCert = certificates[certificateId];
        newCert.id = certificateId;
        newCert.passportId = passportId;
        newCert.certificateType = certificateType;
        newCert.certificateNumber = certificateNumber;
        newCert.issuingAuthority = issuingAuthority;
        newCert.issueDate = issueDate;
        newCert.expiryDate = expiryDate;
        newCert.ipfsCID = ipfsCID;
        newCert.isValid = true;
        newCert.createdAt = block.timestamp;
        newCert.issuer = msg.sender;

        // Update mappings
        passportCertificates[passportId].push(certificateId);
        totalCertificatesCreated++;
        totalFeesCollected += certificateCreationFee;

        emit CertificateCreated(certificateId, passportId, certificateType, expiryDate);
        return certificateId;
    }

    // ============ ADMIN FUNCTIONS WITH MULTI-SIG SUPPORT ============

    /**
     * @dev Update fees with validation
     */
    function updateFees(
        uint256 newBrandRegistrationFee,
        uint256 newPassportCreationFee,
        uint256 newCertificateCreationFee
    ) external onlyRole(ADMIN_ROLE) {
        require(newBrandRegistrationFee <= MAX_FEE, "Brand fee too high");
        require(newPassportCreationFee <= MAX_FEE, "Passport fee too high");
        require(newCertificateCreationFee <= MAX_FEE, "Certificate fee too high");

        brandRegistrationFee = newBrandRegistrationFee;
        passportCreationFee = newPassportCreationFee;
        certificateCreationFee = newCertificateCreationFee;
    }

    /**
     * @dev Set treasury with security checks
     */
    function setTreasury(address newTreasury) 
        external 
        onlyRole(ADMIN_ROLE) 
        treasuryNotLocked 
    {
        TrataTechSecurityEnhanced.validateAddress(newTreasury);

        address oldTreasury = treasury;
        treasury = newTreasury;

        emit TreasuryUpdated(oldTreasury, newTreasury);
    }

    /**
     * @dev Secure fee withdrawal with multi-step process
     */
    function withdrawFees() 
        external 
        onlyRole(ADMIN_ROLE) 
        treasuryNotLocked
        nonReentrant 
    {
        uint256 balance = address(this).balance;
        require(balance > 0, "No fees to withdraw");

        bool success = TrataTechSecurityEnhanced.safeTransferETH(treasury, balance);
        require(success, "Transfer to treasury failed");
    }

    /**
     * @dev Circuit breaker controls
     */
    function toggleBrandRegistration() external onlyRole(ADMIN_ROLE) {
        brandRegistrationEnabled = !brandRegistrationEnabled;
        emit CircuitBreakerActivated("brand_registration", msg.sender);
    }

    function togglePassportCreation() external onlyRole(ADMIN_ROLE) {
        passportCreationEnabled = !passportCreationEnabled;
        emit CircuitBreakerActivated("passport_creation", msg.sender);
    }

    function toggleCertificateCreation() external onlyRole(ADMIN_ROLE) {
        certificateCreationEnabled = !certificateCreationEnabled;
        emit CircuitBreakerActivated("certificate_creation", msg.sender);
    }

    /**
     * @dev Lock treasury operations (emergency only)
     */
    function lockTreasury() external onlyRole(ADMIN_ROLE) {
        treasuryLocked = true;
    }

    // ============ INTERNAL HELPER FUNCTIONS ============

    /**
     * @dev Check daily action limits
     */
    function _checkDailyLimit() internal view {
        if (block.timestamp - _lastResetTime[msg.sender] >= 1 days) {
            return; // Reset period passed
        }

        require(_dailyActionCount[msg.sender] < DAILY_ACTION_LIMIT, "Daily limit exceeded");
    }

    /**
     * @dev Update daily action counter
     */
    function _updateDailyCounter() internal {
        if (block.timestamp - _lastResetTime[msg.sender] >= 1 days) {
            _dailyActionCount[msg.sender] = 1;
            _lastResetTime[msg.sender] = block.timestamp;
        } else {
            _dailyActionCount[msg.sender]++;
        }

        if (_dailyActionCount[msg.sender] >= DAILY_ACTION_LIMIT) {
            emit DailyLimitExceeded(msg.sender, _dailyActionCount[msg.sender]);
        }
    }

    // ============ VIEW FUNCTIONS ============

    /**
     * @dev Get security metrics
     */
    function getSecurityMetrics() external view returns (
        uint256 totalBrands,
        uint256 totalPassports,
        uint256 totalCertificates,
        uint256 totalFees,
        bool brandRegEnabled,
        bool passportEnabled,
        bool certEnabled
    ) {
        return (
            totalBrandsCreated,
            totalPassportsCreated,
            totalCertificatesCreated,
            totalFeesCollected,
            brandRegistrationEnabled,
            passportCreationEnabled,
            certificateCreationEnabled
        );
    }

    /**
     * @dev Get user action status
     */
    function getUserActionStatus(address user) external view returns (
        uint256 lastActionTime,
        uint256 dailyCount,
        uint256 resetTime,
        bool canAct
    ) {
        return (
            _lastActionTime[user],
            _dailyActionCount[user],
            _lastResetTime[user],
            block.timestamp >= _lastActionTime[user] + TrataTechSecurityEnhanced.RATE_LIMIT_DURATION &&
            _dailyActionCount[user] < DAILY_ACTION_LIMIT
        );
    }

    // ============ OVERRIDE FUNCTIONS FOR ERC2771Context ============

    function _msgSender() internal view override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (address) {
        return ERC2771ContextUpgradeable._msgSender();
    }

    function _msgData() internal view override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (bytes calldata) {
        return ERC2771ContextUpgradeable._msgData();
    }

    function _contextSuffixLength() internal view override(ContextUpgradeable, ERC2771ContextUpgradeable) returns (uint256) {
        return ERC2771ContextUpgradeable._contextSuffixLength();
    }

    // ============ STORAGE GAP FOR UPGRADE SAFETY ============

    /**
     * @dev Extended storage gap for upgrade safety
     * Reduced from 100 to 95 slots to accommodate ERC2771Context storage
     */
    uint256[95] private __gap;
}

contracts/TrataTechProvenance_Fixed.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import "./TrataTechSecurityEnhanced.sol";

/**
 * @title TrataTechProvenance_Fixed
 * @dev SECURITY-ENHANCED Provenance Contract for maintaining immutable logs of transfers and service history
 * @dev Fixed all critical vulnerabilities from security audit
 */
contract TrataTechProvenance_Fixed is AccessControl, ERC2771Context, Pausable, ReentrancyGuard {

    using ECDSA for bytes32;
    using TrataTechSecurityEnhanced for string;
    using TrataTechSecurityEnhanced for address;
    using TrataTechSecurityEnhanced for uint256;

    // ============ ROLES ============

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant RECORDER_ROLE = keccak256("RECORDER_ROLE");
    bytes32 public constant SERVICE_PROVIDER_ROLE = keccak256("SERVICE_PROVIDER_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");

    // ============ STRUCTS ============

    struct ProvenanceEntry {
        uint256 entryId;
        uint256 passportId;
        ProvenanceType entryType;
        address from;
        address to;
        uint256 timestamp;
        string location;
        string description;
        string ipfsCID;
        string metadataHash;
        bool isValid;
        address recorder;
        mapping(string => string) additionalData;
        string[] dataKeys;
    }

    struct ServiceRecord {
        uint256 serviceId;
        uint256 passportId;
        string serviceType;
        string serviceProvider;
        string serviceDescription;
        uint256 serviceDate;
        uint256 nextServiceDate;
        string ipfsCID;
        string certificateNumber;
        bool isValid;
        address serviceProviderAddress;
        mapping(string => string) serviceDetails;
        string[] detailKeys;
    }

    struct TransferHistory {
        uint256 passportId;
        uint256[] transferEntryIds;
        uint256[] serviceEntryIds;
        uint256 totalTransfers;
        uint256 totalServices;
        address currentOwner;
        uint256 lastTransferDate;
    }

    enum ProvenanceType {
        MANUFACTURING,
        TRANSFER,
        SERVICE,
        REPAIR,
        MAINTENANCE,
        INSPECTION,
        CERTIFICATION,
        RECALL,
        DISPOSAL,
        CUSTOM
    }

    // ============ STATE VARIABLES ============

    uint256 private _entryIds = 0;
    uint256 private _serviceIds = 0;

    // Mappings
    mapping(uint256 => ProvenanceEntry) public provenanceEntries;
    mapping(uint256 => ServiceRecord) public serviceRecords;
    mapping(uint256 => TransferHistory) public transferHistories;
    mapping(uint256 => uint256[]) public passportToEntries;
    mapping(uint256 => uint256[]) public passportToServices;

    // Security enhancements
    mapping(address => uint256) private _lastActionTime;
    mapping(uint256 => uint256) private _entryCreationTime;
    mapping(uint256 => uint256) private _serviceCreationTime;

    // Fee structure with limits
    uint256 public provenanceEntryFee = 0.001 ether;
    uint256 public serviceRecordFee = 0.002 ether;
    uint256 public constant MAX_FEE = 0.1 ether;

    // Circuit breakers
    bool public transfersEnabled = true;
    bool public serviceCreationEnabled = true;
    bool public batchOperationsEnabled = true;

    // Counters for monitoring
    uint256 public totalEntriesCreated;
    uint256 public totalServicesCreated;
    uint256 public totalFeesCollected;

    // ============ EVENTS ============

    event ProvenanceEntryCreated(
        uint256 indexed entryId,
        uint256 indexed passportId,
        ProvenanceType entryType,
        address indexed from,
        address to,
        string location,
        string ipfsCID
    );

    event ServiceRecordCreated(
        uint256 indexed serviceId,
        uint256 indexed passportId,
        string serviceType,
        string serviceProvider,
        string ipfsCID
    );

    event BatchOperationCompleted(uint256 entriesCreated, uint256 gasUsed);
    event CircuitBreakerTriggered(string operation, address triggeredBy);
    event SecurityViolationDetected(string violationType, address violator);
    event FeesWithdrawn(address recipient, uint256 amount);

    // ============ MODIFIERS ============

    modifier onlyAuthorizedRole(bytes32 role) {
        require(hasRole(role, msg.sender), "AccessControl: account missing role");
        _;
    }

    modifier rateLimited() {
        TrataTechSecurityEnhanced.checkRateLimit(_lastActionTime[msg.sender]);
        TrataTechSecurityEnhanced.updateRateLimit(msg.sender, _lastActionTime);
        _;
    }

    modifier whenTransfersEnabled() {
        require(transfersEnabled, "Transfers are disabled");
        _;
    }

    modifier whenServiceCreationEnabled() {
        require(serviceCreationEnabled, "Service creation is disabled");
        _;
    }

    modifier whenBatchOperationsEnabled() {
        require(batchOperationsEnabled, "Batch operations are disabled");
        _;
    }

    modifier validEntry(uint256 entryId) {
        require(provenanceEntries[entryId].entryId != 0, "Entry does not exist");
        require(provenanceEntries[entryId].isValid, "Entry is invalid");
        _;
    }

    // ============ CONSTRUCTOR ============

    constructor(address trustedForwarder) ERC2771Context(trustedForwarder) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(RECORDER_ROLE, msg.sender);
        _grantRole(SERVICE_PROVIDER_ROLE, msg.sender);
        _grantRole(OPERATOR_ROLE, msg.sender);

        _entryIds = 1;
        _serviceIds = 1;
    }

    // ============ PROVENANCE ENTRY MANAGEMENT ============

    /**
     * @dev Create a new provenance entry with comprehensive security checks
     */
    function createProvenanceEntry(
        uint256 passportId,
        ProvenanceType entryType,
        address from,
        address to,
        string memory location,
        string memory description,
        string memory ipfsCID,
        string memory metadataHash,
        string[] memory additionalData
    ) external 
      payable
      onlyAuthorizedRole(RECORDER_ROLE)
      whenNotPaused
      whenTransfersEnabled
      rateLimited
      nonReentrant 
    {
        // Process payment with automatic refund
        TrataTechSecurityEnhanced.processPaymentWithRefund(provenanceEntryFee);

        // Validate all inputs
        require(passportId > 0, "Invalid passport ID");
        TrataTechSecurityEnhanced.validateAddress(from);
        TrataTechSecurityEnhanced.validateAddress(to);
        TrataTechSecurityEnhanced.validateString(location);
        TrataTechSecurityEnhanced.validateString(description);
        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);
        TrataTechSecurityEnhanced.validateString(metadataHash);
        TrataTechSecurityEnhanced.validateArraySize(additionalData.length);

        _entryIds++;
        uint256 entryId = _entryIds;

        ProvenanceEntry storage newEntry = provenanceEntries[entryId];
        newEntry.entryId = entryId;
        newEntry.passportId = passportId;
        newEntry.entryType = entryType;
        newEntry.from = from;
        newEntry.to = to;
        newEntry.timestamp = block.timestamp;
        newEntry.location = location;
        newEntry.description = description;
        newEntry.ipfsCID = ipfsCID;
        newEntry.metadataHash = metadataHash;
        newEntry.isValid = true;
        newEntry.recorder = msg.sender;

        // Process additional data with size validation
        TrataTechSecurityEnhanced.processKeyValuePairs(
            additionalData,
            newEntry.additionalData,
            newEntry.dataKeys
        );

        // Update mappings and history
        passportToEntries[passportId].push(entryId);
        _updateTransferHistory(passportId, entryId, to, entryType);

        // Update counters
        totalEntriesCreated++;
        totalFeesCollected += provenanceEntryFee;
        _entryCreationTime[entryId] = block.timestamp;

        emit ProvenanceEntryCreated(entryId, passportId, entryType, from, to, location, ipfsCID);
    }

    /**
     * @dev Create multiple provenance entries with enhanced security
     */
    function createBatchProvenanceEntries(
        uint256[] memory passportIds,
        ProvenanceType[] memory entryTypes,
        address[] memory froms,
        address[] memory tos,
        string[] memory locations,
        string[] memory descriptions,
        string[] memory ipfsCIDs,
        string[] memory metadataHashes
    ) external 
      payable
      onlyAuthorizedRole(RECORDER_ROLE)
      whenNotPaused
      whenBatchOperationsEnabled
      rateLimited
      nonReentrant 
    {
        uint256 batchSize = passportIds.length;
        TrataTechSecurityEnhanced.validateBatchSize(batchSize);

        // Validate array lengths match
        require(
            batchSize == entryTypes.length &&
            batchSize == froms.length &&
            batchSize == tos.length &&
            batchSize == locations.length &&
            batchSize == descriptions.length &&
            batchSize == ipfsCIDs.length &&
            batchSize == metadataHashes.length,
            "Array lengths must match"
        );

        uint256 totalCost = provenanceEntryFee * batchSize;
        TrataTechSecurityEnhanced.processPaymentWithRefund(totalCost);

        uint256 startGas = gasleft();
        uint256 entriesCreated = 0;

        for (uint256 i = 0; i < batchSize; i++) {
            _createSingleEntry(
                passportIds[i],
                entryTypes[i], 
                froms[i],
                tos[i],
                locations[i],
                descriptions[i],
                ipfsCIDs[i],
                metadataHashes[i]
            );
            entriesCreated++;
        }

        uint256 gasUsed = startGas - gasleft();
        totalFeesCollected += totalCost;

        emit BatchOperationCompleted(entriesCreated, gasUsed);
    }

    /**
     * @dev Internal function to create single entry with validation
     */
    function _createSingleEntry(
        uint256 passportId,
        ProvenanceType entryType,
        address from,
        address to,
        string memory location,
        string memory description,
        string memory ipfsCID,
        string memory metadataHash
    ) internal {
        require(passportId > 0, "Invalid passport ID");
        TrataTechSecurityEnhanced.validateAddress(from);
        TrataTechSecurityEnhanced.validateAddress(to);
        TrataTechSecurityEnhanced.validateString(location);
        TrataTechSecurityEnhanced.validateString(description);
        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);
        TrataTechSecurityEnhanced.validateString(metadataHash);

        _entryIds++;
        uint256 entryId = _entryIds;

        ProvenanceEntry storage newEntry = provenanceEntries[entryId];
        newEntry.entryId = entryId;
        newEntry.passportId = passportId;
        newEntry.entryType = entryType;
        newEntry.from = from;
        newEntry.to = to;
        newEntry.timestamp = block.timestamp;
        newEntry.location = location;
        newEntry.description = description;
        newEntry.ipfsCID = ipfsCID;
        newEntry.metadataHash = metadataHash;
        newEntry.isValid = true;
        newEntry.recorder = msg.sender;

        passportToEntries[passportId].push(entryId);
        _updateTransferHistory(passportId, entryId, to, entryType);

        totalEntriesCreated++;
        _entryCreationTime[entryId] = block.timestamp;

        emit ProvenanceEntryCreated(entryId, passportId, entryType, from, to, location, ipfsCID);
    }

    // ============ SERVICE RECORD MANAGEMENT ============

    /**
     * @dev Create a service record with security enhancements
     */
    function createServiceRecord(
        uint256 passportId,
        string memory serviceType,
        string memory serviceProvider,
        string memory serviceDescription,
        uint256 serviceDate,
        uint256 nextServiceDate,
        string memory ipfsCID,
        string memory certificateNumber,
        string[] memory serviceDetails
    ) external 
      payable
      onlyAuthorizedRole(SERVICE_PROVIDER_ROLE)
      whenNotPaused
      whenServiceCreationEnabled
      rateLimited
      nonReentrant 
    {
        TrataTechSecurityEnhanced.processPaymentWithRefund(serviceRecordFee);

        // Validate inputs
        require(passportId > 0, "Invalid passport ID");
        TrataTechSecurityEnhanced.validateString(serviceType);
        TrataTechSecurityEnhanced.validateString(serviceProvider);
        TrataTechSecurityEnhanced.validateString(serviceDescription);
        TrataTechSecurityEnhanced.validateTimestamp(serviceDate);
        TrataTechSecurityEnhanced.validateDateRange(serviceDate, nextServiceDate);
        TrataTechSecurityEnhanced.validateIPFSCID(ipfsCID);
        TrataTechSecurityEnhanced.validateArraySize(serviceDetails.length);

        _serviceIds++;
        uint256 serviceId = _serviceIds;

        ServiceRecord storage newService = serviceRecords[serviceId];
        newService.serviceId = serviceId;
        newService.passportId = passportId;
        newService.serviceType = serviceType;
        newService.serviceProvider = serviceProvider;
        newService.serviceDescription = serviceDescription;
        newService.serviceDate = serviceDate;
        newService.nextServiceDate = nextServiceDate;
        newService.ipfsCID = ipfsCID;
        newService.certificateNumber = certificateNumber;
        newService.isValid = true;
        newService.serviceProviderAddress = msg.sender;

        // Process service details with validation
        TrataTechSecurityEnhanced.processKeyValuePairs(
            serviceDetails,
            newService.serviceDetails,
            newService.detailKeys
        );

        // Update mappings and history
        passportToServices[passportId].push(serviceId);
        _updateServiceHistory(passportId, serviceId);

        totalServicesCreated++;
        totalFeesCollected += serviceRecordFee;
        _serviceCreationTime[serviceId] = block.timestamp;

        emit ServiceRecordCreated(serviceId, passportId, serviceType, serviceProvider, ipfsCID);
    }

    // ============ ADMIN FUNCTIONS WITH SECURITY ============

    /**
     * @dev Set fees with validation and limits
     */
    function setFees(uint256 newProvenanceFee, uint256 newServiceFee) 
        external 
        onlyAuthorizedRole(ADMIN_ROLE) 
    {
        require(newProvenanceFee <= MAX_FEE, "Provenance fee too high");
        require(newServiceFee <= MAX_FEE, "Service fee too high");

        provenanceEntryFee = newProvenanceFee;
        serviceRecordFee = newServiceFee;
    }

    /**
     * @dev Emergency controls with role-based access
     */
    function toggleTransfers() external onlyRole(ADMIN_ROLE) {
        transfersEnabled = !transfersEnabled;
        emit CircuitBreakerTriggered("transfers", msg.sender);
    }

    function toggleServiceCreation() external onlyRole(ADMIN_ROLE) {
        serviceCreationEnabled = !serviceCreationEnabled;
        emit CircuitBreakerTriggered("service_creation", msg.sender);
    }

    function toggleBatchOperations() external onlyRole(ADMIN_ROLE) {
        batchOperationsEnabled = !batchOperationsEnabled;
        emit CircuitBreakerTriggered("batch_operations", msg.sender);
    }

    /**
     * @dev Secure fee withdrawal with reentrancy protection
     */
    function withdrawFees(address payable recipient) 
        external 
        onlyAuthorizedRole(ADMIN_ROLE) 
        nonReentrant 
    {
        TrataTechSecurityEnhanced.validateAddress(recipient);

        uint256 balance = address(this).balance;
        require(balance > 0, "No fees to withdraw");

        // Use secure transfer
        bool success = TrataTechSecurityEnhanced.safeTransferETH(recipient, balance);
        require(success, "Transfer failed");

        emit FeesWithdrawn(recipient, balance);
    }

    /**
     * @dev Emergency pause
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    // ============ INTERNAL HELPER FUNCTIONS ============

    /**
     * @dev Update transfer history with validation
     */
    function _updateTransferHistory(
        uint256 passportId, 
        uint256 entryId, 
        address to, 
        ProvenanceType /* entryType */
    ) internal {
        TransferHistory storage history = transferHistories[passportId];

        if (history.passportId == 0) {
            history.passportId = passportId;
            history.totalTransfers = 0;
            history.totalServices = 0;
        }

        history.transferEntryIds.push(entryId);
        history.totalTransfers++;
        history.currentOwner = to;
        history.lastTransferDate = block.timestamp;
    }

    /**
     * @dev Update service history
     */
    function _updateServiceHistory(uint256 passportId, uint256 serviceId) internal {
        TransferHistory storage history = transferHistories[passportId];

        if (history.passportId == 0) {
            history.passportId = passportId;
            history.totalTransfers = 0;
            history.totalServices = 0;
        }

        history.serviceEntryIds.push(serviceId);
        history.totalServices++;
    }

    // ============ VIEW FUNCTIONS ============

    /**
     * @dev Get paginated entries to prevent DoS
     */
    function getPassportEntriesPaginated(
        uint256 passportId, 
        uint256 offset, 
        uint256 limit
    ) external view returns (uint256[] memory) {
        require(limit <= 50, "Limit too high"); // Prevent large data retrieval

        uint256[] storage allEntries = passportToEntries[passportId];
        uint256 totalEntries = allEntries.length;

        if (offset >= totalEntries) {
            return new uint256[](0);
        }

        uint256 end = offset + limit;
        if (end > totalEntries) {
            end = totalEntries;
        }

        uint256[] memory result = new uint256[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            result[i - offset] = allEntries[i];
        }

        return result;
    }

    /**
     * @dev Get security metrics
     */
    function getSecurityMetrics() external view returns (
        uint256 totalEntries,
        uint256 totalServices,
        uint256 totalFees,
        bool transfersActive,
        bool servicesActive,
        bool batchActive
    ) {
        return (
            totalEntriesCreated,
            totalServicesCreated,
            totalFeesCollected,
            transfersEnabled,
            serviceCreationEnabled,
            batchOperationsEnabled
        );
    }

    // ============ RECEIVE FUNCTION ============

    receive() external payable {
        // Contract can receive ETH for fees
    }

    // ============ OVERRIDE FUNCTIONS FOR ERC2771Context ============

    function _msgSender() internal view override(Context, ERC2771Context) returns (address) {
        return ERC2771Context._msgSender();
    }

    function _msgData() internal view override(Context, ERC2771Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength() internal view override(Context, ERC2771Context) returns (uint256) {
        return ERC2771Context._contextSuffixLength();
    }
}

contracts/TrataTechSecurityEnhanced.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title TrataTechSecurityEnhanced
 * @dev Enhanced security library with comprehensive validation and protection mechanisms
 * @author TrataTech Security Team
 */
library TrataTechSecurityEnhanced {

    // ============ CONSTANTS ============

    uint256 public constant MAX_ARRAY_SIZE = 10;
    uint256 public constant MAX_BATCH_SIZE = 5;
    uint256 public constant MIN_STRING_LENGTH = 1;
    uint256 public constant MAX_STRING_LENGTH = 256;
    uint256 public constant MAX_PERCENTAGE = 1000; // 10%
    uint256 public constant FEE_DENOMINATOR = 10000; // 100% = 10000 basis points
    uint256 public constant MIN_TIMELOCK = 1 days;
    uint256 public constant MAX_TIMELOCK = 30 days;
    uint256 public constant RATE_LIMIT_DURATION = 60; // 60 seconds

    // ============ ERRORS ============

    error ArrayTooLarge(uint256 size, uint256 maxSize);
    error InvalidStringLength(uint256 length);
    error InvalidAddress(address addr);
    error InvalidPercentage(uint256 percentage);
    error InvalidAmount(uint256 amount);
    error InvalidTimestamp(uint256 timestamp);
    error InvalidIPFSCID(string cid);
    error RateLimitExceeded(uint256 timeRemaining);
    error InsufficientPayment(uint256 sent, uint256 required);
    error RefundFailed(uint256 amount);

    // ============ EVENTS ============

    event ValidationPerformed(string validationType, bool success);
    event RateLimitApplied(address user, uint256 nextAllowedTime);
    event RefundProcessed(address recipient, uint256 amount);

    // ============ INPUT VALIDATION FUNCTIONS ============

    /**
     * @dev Validate array size to prevent DoS attacks
     * @param arrayLength Length of array to validate
     */
    function validateArraySize(uint256 arrayLength) internal pure {
        if (arrayLength > MAX_ARRAY_SIZE) {
            revert ArrayTooLarge(arrayLength, MAX_ARRAY_SIZE);
        }
    }

    /**
     * @dev Validate batch operation size
     * @param batchSize Size of batch operation
     */
    function validateBatchSize(uint256 batchSize) internal pure {
        if (batchSize > MAX_BATCH_SIZE) {
            revert ArrayTooLarge(batchSize, MAX_BATCH_SIZE);
        }
    }

    /**
     * @dev Validate string length
     * @param str String to validate
     */
    function validateString(string memory str) internal pure {
        uint256 length = bytes(str).length;
        if (length < MIN_STRING_LENGTH || length > MAX_STRING_LENGTH) {
            revert InvalidStringLength(length);
        }
    }

    /**
     * @dev Validate Ethereum address
     * @param addr Address to validate
     */
    function validateAddress(address addr) internal pure {
        if (addr == address(0)) {
            revert InvalidAddress(addr);
        }
    }

    /**
     * @dev Validate percentage (in basis points)
     * @param percentage Percentage to validate
     */
    function validatePercentage(uint256 percentage) internal pure {
        if (percentage > MAX_PERCENTAGE) {
            revert InvalidPercentage(percentage);
        }
    }

    /**
     * @dev Validate amount is greater than zero
     * @param amount Amount to validate
     */
    function validateAmount(uint256 amount) internal pure {
        if (amount == 0) {
            revert InvalidAmount(amount);
        }
    }

    /**
     * @dev Validate timestamp is not in the future
     * @param timestamp Timestamp to validate
     */
    function validateTimestamp(uint256 timestamp) internal view {
        if (timestamp > block.timestamp) {
            revert InvalidTimestamp(timestamp);
        }
    }

    /**
     * @dev Validate future timestamp
     * @param timestamp Timestamp to validate
     */
    function validateFutureTimestamp(uint256 timestamp) internal view {
        if (timestamp <= block.timestamp) {
            revert InvalidTimestamp(timestamp);
        }
    }

    /**
     * @dev Enhanced IPFS CID validation
     * @param cid IPFS CID to validate
     */
    function validateIPFSCID(string memory cid) internal pure {
        bytes memory cidBytes = bytes(cid);
        if (cidBytes.length < 46 || cidBytes.length > 90) {
            revert InvalidIPFSCID(cid);
        }

        // Check for valid IPFS CID prefixes
        bool validPrefix = false;
        if (cidBytes.length >= 2) {
            // Check for "Qm" prefix (CIDv0)
            if (cidBytes[0] == 0x51 && cidBytes[1] == 0x6D) {
                validPrefix = true;
            }
            // Check for base32 encoded CIDv1
            else if (cidBytes.length >= 59) {
                validPrefix = true;
            }
        }

        if (!validPrefix) {
            revert InvalidIPFSCID(cid);
        }
    }

    // ============ PAYMENT HANDLING FUNCTIONS ============

    /**
     * @dev Process payment with automatic refund for overpayment
     * @param requiredAmount Required payment amount
     */
    function processPaymentWithRefund(uint256 requiredAmount) internal {
        if (msg.value < requiredAmount) {
            revert InsufficientPayment(msg.value, requiredAmount);
        }

        // Refund excess payment
        if (msg.value > requiredAmount) {
            uint256 refund = msg.value - requiredAmount;
            (bool success, ) = payable(msg.sender).call{value: refund}("");
            if (!success) {
                revert RefundFailed(refund);
            }
            emit RefundProcessed(msg.sender, refund);
        }
    }

    /**
     * @dev Calculate fee amount
     * @param amount Base amount
     * @param feePercentage Fee percentage in basis points
     */
    function calculateFee(uint256 amount, uint256 feePercentage) internal pure returns (uint256) {
        return (amount * feePercentage) / FEE_DENOMINATOR;
    }

    // ============ RATE LIMITING FUNCTIONS ============

    /**
     * @dev Check and enforce rate limiting
     * @param lastActionTime User's last action timestamp
     */
    function checkRateLimit(uint256 lastActionTime) internal view {
        uint256 timeSinceLastAction = block.timestamp - lastActionTime;
        if (timeSinceLastAction < RATE_LIMIT_DURATION) {
            uint256 timeRemaining = RATE_LIMIT_DURATION - timeSinceLastAction;
            revert RateLimitExceeded(timeRemaining);
        }
    }

    /**
     * @dev Update rate limit timestamp
     * @param user User address
     * @param lastActionTimes Mapping to update
     */
    function updateRateLimit(address user, mapping(address => uint256) storage lastActionTimes) internal {
        lastActionTimes[user] = block.timestamp;
        emit RateLimitApplied(user, block.timestamp + RATE_LIMIT_DURATION);
    }

    // ============ ARRAY PROCESSING FUNCTIONS ============

    /**
     * @dev Process key-value pairs with size validation
     * @param keyValuePairs Array of key-value pairs (even indices = keys, odd = values)
     * @param dataStorage Storage mapping to update
     * @param keysArray Array to store keys
     */
    function processKeyValuePairs(
        string[] memory keyValuePairs,
        mapping(string => string) storage dataStorage,
        string[] storage keysArray
    ) internal {
        validateArraySize(keyValuePairs.length);

        for (uint256 i = 0; i < keyValuePairs.length; i += 2) {
            if (i + 1 < keyValuePairs.length) {
                string memory key = keyValuePairs[i];
                string memory value = keyValuePairs[i + 1];

                validateString(key);
                // Value can be empty, so no validation needed

                dataStorage[key] = value;
                keysArray.push(key);
            }
        }
    }

    // ============ ACCESS CONTROL FUNCTIONS ============

    /**
     * @dev Validate multiple role authorization
     * @param account Account to check
     * @param roles Array of role mappings
     */
    function validateMultipleRoles(
        address account,
        mapping(address => bool)[] storage roles
    ) internal view returns (bool) {
        for (uint256 i = 0; i < roles.length; i++) {
            if (roles[i][account]) {
                return true;
            }
        }
        return false;
    }

    // ============ EMERGENCY FUNCTIONS ============

    /**
     * @dev Safe ETH transfer with gas limit
     * @param to Recipient address
     * @param amount Amount to transfer
     */
    function safeTransferETH(address to, uint256 amount) internal returns (bool) {
        validateAddress(to);
        validateAmount(amount);

        (bool success, ) = payable(to).call{value: amount, gas: 2300}("");
        return success;
    }

    /**
     * @dev Calculate storage slot for upgradeable contracts
     * @param baseSlot Base storage slot
     * @param offset Offset from base
     */
    function calculateStorageSlot(bytes32 baseSlot, uint256 offset) internal pure returns (bytes32) {
        return bytes32(uint256(baseSlot) + offset);
    }

    // ============ UTILITY FUNCTIONS ============

    /**
     * @dev Generate unique ID with collision resistance
     * @param baseId Base ID
     * @param timestamp Current timestamp
     * @param sender Sender address
     */
    function generateUniqueId(
        uint256 baseId,
        uint256 timestamp,
        address sender
    ) internal view returns (bytes32) {
        return keccak256(abi.encodePacked(baseId, timestamp, sender, block.prevrandao));
    }

    /**
     * @dev Validate and process expiry date
     * @param issueDate Issue date
     * @param expiryDate Expiry date
     */
    function validateDateRange(uint256 issueDate, uint256 expiryDate) internal view {
        validateTimestamp(issueDate); // Issue date can't be future
        if (expiryDate <= issueDate) {
            revert InvalidTimestamp(expiryDate);
        }
    }

    /**
     * @dev Check if current time is within date range
     * @param startDate Start date
     * @param endDate End date
     */
    function isWithinDateRange(uint256 startDate, uint256 endDate) internal view returns (bool) {
        return block.timestamp >= startDate && block.timestamp <= endDate;
    }
}

